insert into public.wine_entities (id, name, canonical_name, entity_type, country, region, subregion, aliases, attributes, base_rarity, sommelier_note)
values
  ('app-pauillac', 'Pauillac AOC', 'Pauillac', 'appellation', 'France', 'Bordeaux', 'Haut-Médoc (Left Bank)', ARRAY['Pauillac', 'Pauillac AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855","Grand_Cru"],"soils":["gravel_alluvial"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","long_cellar_20yr","full_bodied_high_abv"],"varietalTraits":["bordeaux_family","multi_blend_tradition","thick_skin_late_ripening"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 18, 'Home to three of the five 1855 First Growths (Lafite, Latour, Mouton). Deep Günzian gravel mounds over limestone drain rapidly, allowing late-ripening Cabernet Sauvignon to achieve cassis, cedar, and graphite perfection.'),
  ('app-pomerol', 'Pomerol AOC', 'Pomerol', 'appellation', 'France', 'Bordeaux', 'Libournais (Right Bank)', ARRAY['Pomerol', 'Pomerol AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC"],"soils":["iron_clay","gravel_alluvial","clay_limestone"],"climates":["maritime"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Merlot","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 28, 'Famous for the blue smectite clay and iron-rich ''crasse de fer'' subsoils on its high plateau (home to Pétrus and Le Pin). Uniquely among elite Bordeaux appellations, Pomerol has no official cru hierarchy.'),
  ('app-saint-emilion', 'Saint-Émilion Grand Cru AOC', 'Saint-Émilion', 'appellation', 'France', 'Bordeaux', 'Libournais (Right Bank)', ARRAY['Saint-Emilion', 'St-Emilion', 'Saint-Émilion AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["clay_limestone","limestone_chalk","gravel_alluvial"],"climates":["maritime"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Merlot","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder"],"heritage":["unesco_landscape","monastic_origin"]}'::jsonb, 20, 'First wine landscape inscribed by UNESCO (1999). Divided between the asteriated limestone plateau (''côtes'') and gravelly alluvial terraces near Pomerol where Cabernet Franc shines at Cheval Blanc.'),
  ('app-sauternes', 'Sauternes AOC', 'Sauternes', 'appellation', 'France', 'Bordeaux', 'Graves / Sauternais', ARRAY['Sauternes', 'Sauternes-Barsac']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855","Grand_Cru"],"soils":["gravel_alluvial","clay_limestone"],"climates":["maritime","cooling_fog_current"],"waterBodies":["gironde_estuary","major_river"],"styles":["botrytis_sweet"],"vinification":["new_french_oak"],"sensory":["honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition","thin_skin_early_ripening"],"primaryGrapes":["Sémillon","Sauvignon Blanc","Muscadelle"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 26, 'Autumn mists generated where the cold spring-fed Ciron tributary meets the warmer Garonne River trigger Botrytis cinerea (noble rot) on thin-skinned Sémillon, crowned by Premier Cru Supérieur Château d''Yquem.'),
  ('app-margaux', 'Margaux AOC', 'Margaux', 'appellation', 'France', 'Bordeaux', 'Haut-Médoc (Left Bank)', ARRAY['Margaux', 'Margaux AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855"],"soils":["gravel_alluvial"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 19, 'The southern communal appellation of the Médoc, around 45°N, with the largest cluster of 1855 classed growths and the First Growth Château Margaux. Deep gravel gives Cabernet-led blends their perfume; pockets of clay explain a higher Merlot share than in Pauillac.'),
  ('app-saint-julien', 'Saint-Julien AOC', 'Saint-Julien', 'appellation', 'France', 'Bordeaux', 'Haut-Médoc (Left Bank)', ARRAY['Saint-Julien', 'Saint Julien', 'St-Julien', 'Saint-Julien AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Classed_Growth_1855"],"soils":["gravel_alluvial"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 23, 'A gravel commune between Pauillac and Margaux. The 1855 list gave it classed growths, including the Léovilles and Ducru-Beaucaillou, but no First Growth. Cabernet Sauvignon leads the blends.'),
  ('app-saint-estephe', 'Saint-Estèphe AOC', 'Saint-Estèphe', 'appellation', 'France', 'Bordeaux', 'Haut-Médoc (Left Bank)', ARRAY['Saint-Estèphe', 'Saint Estephe', 'St-Estephe', 'Saint-Estèphe AOC']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Classed_Growth_1855"],"soils":["gravel_alluvial","clay_limestone"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 27, 'The northernmost of the four great Médoc communal appellations, just above 45°N. Clay mixed with gravel favors more Merlot than in Pauillac. Its 1855 classed growths include Cos d''Estournel and Montrose; there is no First Growth.'),
  ('app-champagne', 'Champagne AOC', 'Champagne', 'appellation', 'France', 'Champagne', 'Montagne de Reims / Côte des Blancs / Vallée de la Marne', ARRAY['Champagne', 'Champagne Grand Cru']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["limestone_chalk","kimmeridgian_marl"],"climates":["continental","maritime"],"waterBodies":["major_river"],"styles":["sparkling_traditional"],"vinification":["sur_lie_autolysis","extended_aging_36m"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","multi_blend_tradition"],"primaryGrapes":["Chardonnay","Pinot Noir","Pinot Meunier"],"bottleShapes":["champagne_heavy"],"heritage":["unesco_landscape","monastic_origin","codified_pre_1855"]}'::jsonb, 10, 'At ~49°N latitude, Belemnite and Micraster chalk subsoils act as thermal regulators and water reservoirs, giving razor-sharp acidity ideal for secondary fermentation in bottle and extended lees autolysis.'),
  ('app-chablis', 'Chablis AOC', 'Chablis', 'appellation', 'France', 'Burgundy', 'Yonne / Lower Burgundy', ARRAY['Chablis', 'Chablis Grand Cru']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["kimmeridgian_marl","limestone_chalk"],"climates":["continental"],"waterBodies":["major_river"],"styles":["dry_white"],"vinification":["amphora_concrete_unoaked","sur_lie_autolysis","large_neutral_botte_foudre"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["burgundy_family","single_varietal_strict"],"primaryGrapes":["Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin"]}'::jsonb, 16, '100% Chardonnay grown on Upper Jurassic Kimmeridgian marl rich in fossilized Exogyra virgula oyster shells along the Serein River, yielding flinty, oyster-shell salinity and electric acidity.'),
  ('app-gevrey-chambertin', 'Gevrey-Chambertin AOC', 'Gevrey-Chambertin', 'appellation', 'France', 'Burgundy', 'Côte de Nuits', ARRAY['Gevrey-Chambertin', 'Chambertin Grand Cru']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak","carbonic_whole_cluster"],"sensory":["low_tannin_delicate","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Pinot Noir"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin","unesco_landscape","codified_pre_1855"]}'::jsonb, 24, 'Boasts nine Grand Crus—more than any other village in the Côte d''Or—planted on Bajocian crinoidal limestone and iron-rich marl washed down from the Combe de Lavaux.'),
  ('app-meursault', 'Meursault AOC', 'Meursault', 'appellation', 'France', 'Burgundy', 'Côte de Beaune', ARRAY['Meursault']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental"],"waterBodies":[],"styles":["dry_white"],"vinification":["new_french_oak","sur_lie_autolysis"],"sensory":["saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","single_varietal_strict"],"primaryGrapes":["Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin","unesco_landscape"]}'::jsonb, 28, 'Famed for Premier Crus like Perrières, Genevrières, and Charmes. Combines hazelnut, brioche, and grilled almond richness from barrel fermentation and bâtonnage with crystalline limestone tension.'),
  ('app-morgon', 'Morgon AOC (Beaujolais Cru)', 'Morgon', 'appellation', 'France', 'Burgundy', 'Beaujolais', ARRAY['Morgon', 'Beaujolais Morgon', 'Côte du Py']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["granite","slate_schist","volcanic_basalt"],"climates":["continental"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["carbonic_whole_cluster","large_neutral_botte_foudre"],"sensory":["low_tannin_delicate","violet_rose_floral","earthy_truffle_tar"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Gamay"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","biodynamic_pioneer"]}'::jsonb, 36, 'Centered on the Côte du Py hill of decomposed manganese-rich schist (''roche pourrie'') and blue volcanic diorite. Capable of ''morgonner''—evolving in bottle to resemble structured Côte de Nuits Pinot Noir.'),
  ('app-cote-rotie', 'Côte-Rôtie AOC', 'Côte-Rôtie', 'appellation', 'France', 'Rhône Valley', 'Northern Rhône', ARRAY['Cote-Rotie', 'Côte-Rôtie']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["slate_schist","granite"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red"],"vinification":["co_fermentation","new_french_oak","carbonic_whole_cluster"],"sensory":["rotundone_black_pepper","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["rhone_family"],"primaryGrapes":["Syrah","Viognier"],"bottleShapes":["burgundy_slope"],"heritage":["codified_pre_1855"]}'::jsonb, 25, 'Literally the ''Roasted Slope''—terraced 60° schist and gneiss slopes split between the iron-rich Côte Brune and granite/gneiss Côte Blonde. Appellation law permits co-fermenting up to 20% aromatic white Viognier with Syrah.'),
  ('app-hermitage', 'Hermitage AOC', 'Hermitage', 'appellation', 'France', 'Rhône Valley', 'Northern Rhône', ARRAY['Hermitage', 'Ermitage']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["granite","gravel_alluvial","loess_silt"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red","dry_white"],"vinification":["co_fermentation","new_french_oak","large_neutral_botte_foudre"],"sensory":["rotundone_black_pepper","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["rhone_family"],"primaryGrapes":["Syrah","Marsanne","Roussanne"],"bottleShapes":["burgundy_slope"],"heritage":["codified_pre_1855"]}'::jsonb, 27, 'A single south-facing granitic hill above Tain-l''Hermitage divided into famed lieux-dits like Les Bessards (pure granite) and Le Méal (alluvial glacial pebbles). Up to 15% Marsanne and Roussanne may be co-fermented in red Hermitage.'),
  ('app-chateauneuf-du-pape', 'Châteauneuf-du-Pape AOC', 'Châteauneuf-du-Pape', 'appellation', 'France', 'Rhône Valley', 'Southern Rhône', ARRAY['Chateauneuf-du-Pape', 'Châteauneuf-du-Pape', 'CDP']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC"],"soils":["galets_roules","gravel_alluvial","sand_phylloxera_free","clay_limestone"],"climates":["mediterranean"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red","dry_white"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster","amphora_concrete_unoaked"],"sensory":["full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["rhone_family","multi_blend_tradition"],"primaryGrapes":["Grenache","Syrah","Mourvèdre","Cinsault","Roussanne"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["bush_vines","monastic_origin"]}'::jsonb, 15, 'The 1936 AOC decree, prepared under Baron Le Roy, defined the appellation. Famous for heat-retaining quartzite ''galets roulés'' pebbles (and sandy lieux-dits like Rayas), untrellised gobelet bush vines, and 13 (18 counting color mutations) permitted grape varieties.'),
  ('app-sancerre', 'Sancerre AOC', 'Sancerre', 'appellation', 'France', 'Loire Valley', 'Central Vineyards', ARRAY['Sancerre']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["kimmeridgian_marl","limestone_chalk"],"climates":["continental"],"waterBodies":["loire_river","major_river"],"styles":["dry_white","dry_red","rose_specialist"],"vinification":["amphora_concrete_unoaked","sur_lie_autolysis"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["bordeaux_family","burgundy_family","aromatic_white","single_varietal_strict"],"primaryGrapes":["Sauvignon Blanc","Pinot Noir"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin"]}'::jsonb, 17, 'Defined by three distinct terroirs overlooking the Loire: ''Terres Blanches'' (Kimmeridgian marl shared with Chablis), ''Caillottes'' (pebbly Oxfordian limestone), and ''Silex'' (flint that imparts gunflint smoke).'),
  ('app-savennieres', 'Savennières AOC', 'Savennières', 'appellation', 'France', 'Loire Valley', 'Anjou-Saumur', ARRAY['Savennieres', 'Savennières', 'Coulée de Serrant']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["slate_schist","volcanic_basalt"],"climates":["maritime","steep_heroic_slopes"],"waterBodies":["loire_river","major_river"],"styles":["dry_white"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["laser_high_acid","saline_mineral","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["single_varietal_strict"],"primaryGrapes":["Chenin Blanc"],"bottleShapes":["burgundy_slope"],"heritage":["biodynamic_pioneer","monastic_origin","unesco_landscape"]}'::jsonb, 45, 'Steep south-facing slopes of Armorican schist and volcanic rhyolite above the Loire produce some of the world''s longest-lived dry Chenin Blancs, including the monopole AOC Coulée de Serrant.'),
  ('app-chinon', 'Chinon AOC', 'Chinon', 'appellation', 'France', 'Loire Valley', 'Touraine', ARRAY['Chinon']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["tuffeau","limestone_chalk","gravel_alluvial"],"climates":["maritime","continental"],"waterBodies":["loire_river","major_river"],"styles":["dry_red","rose_specialist","dry_white"],"vinification":["large_neutral_botte_foudre","amphora_concrete_unoaked"],"sensory":["laser_high_acid","violet_rose_floral"],"varietalTraits":["bordeaux_family","single_varietal_strict"],"primaryGrapes":["Cabernet Franc","Chenin Blanc"],"bottleShapes":["burgundy_slope"],"heritage":["unesco_landscape"]}'::jsonb, 35, 'Cabernet Franc benchmark along the Vienne River. Alluvial gravel terraces produce supple, raspberry-scented reds, while steep slopes of Turonian yellow ''tuffeau'' chalk yield structured, cellar-worthy wines.'),
  ('app-muscadet', 'Muscadet Sèvre et Maine AOC', 'Muscadet Sèvre et Maine', 'appellation', 'France', 'Loire Valley', 'Pays Nantais', ARRAY['Muscadet', 'Muscadet Sevre et Maine Sur Lie']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":true,"classifications":["AOC"],"soils":["granite","slate_schist"],"climates":["maritime"],"waterBodies":["loire_river","atlantic_ocean","major_river"],"styles":["dry_white"],"vinification":["sur_lie_autolysis","no_malolactic","amphora_concrete_unoaked"],"sensory":["laser_high_acid","saline_mineral","low_abv_delicate"],"varietalTraits":["burgundy_family","single_varietal_strict"],"primaryGrapes":["Melon de Bourgogne"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 34, 'At the Atlantic mouth of the Loire, Melon de Bourgogne is aged ''Sur Lie'' (on fine dead yeast lees over winter without racking) over gneiss, orthogneiss, and gabbro bedrock, creating brisk sea-spray salinity.'),
  ('app-alsace-grand-cru', 'Alsace Grand Cru AOC', 'Alsace Grand Cru', 'appellation', 'France', 'Alsace', 'Haut-Rhin & Bas-Rhin', ARRAY['Alsace Grand Cru']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["granite","limestone_chalk","volcanic_basalt","slate_schist","clay_limestone"],"climates":["continental","rain_shadow","steep_heroic_slopes"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["laser_high_acid","petrol_tdn","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["aromatic_white","single_varietal_strict"],"primaryGrapes":["Riesling","Gewürztraminer","Pinot Gris","Muscat"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["biodynamic_pioneer"]}'::jsonb, 29, 'Protected by the Vosges Mountains rain shadow, making Colmar one of the driest cities in France. Comprises 51 Grand Cru vineyards (like Rangen''s volcanic grauwacke and Schlossberg''s granite) bottled exclusively in the tall Flûte d''Alsace.'),
  ('app-chateau-chalon', 'Château-Chalon AOC (Jura Vin Jaune)', 'Château-Chalon', 'appellation', 'France', 'Jura', 'Revermont', ARRAY['Chateau-Chalon', 'Château-Chalon', 'Vin Jaune']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["clay_limestone"],"climates":["continental","steep_heroic_slopes"],"waterBodies":[],"styles":["oxidative_biological","dry_white"],"vinification":["flor_yeast","extended_aging_36m","large_neutral_botte_foudre"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Savagnin"],"bottleShapes":["specialty_traditional"],"heritage":["monastic_origin","biodynamic_pioneer"]}'::jsonb, 58, 'Dedicated solely to Vin Jaune from 100% late-harvested Savagnin on blue/grey Liassic marl. Aged untouched for 6 years and 3 months under a veil (''voile'') of yeast without topping up, then bottled in the 62cl ''Clavelin''.'),
  ('app-bandol', 'Bandol AOC', 'Bandol', 'appellation', 'France', 'Provence', 'Var Coast', ARRAY['Bandol']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AOC"],"soils":["limestone_chalk","clay_limestone"],"climates":["mediterranean","steep_heroic_slopes"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","rose_specialist","dry_white"],"vinification":["large_neutral_botte_foudre"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["rhone_family","multi_blend_tradition","thick_skin_late_ripening"],"primaryGrapes":["Mourvèdre","Grenache","Cinsault"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines"]}'::jsonb, 37, 'A sunlit Mediterranean amphitheater of terraced ''restanques'' where late-ripening Mourvèdre must constitute at least 50% of red blends and age a minimum of 18 months in large oak foudres.'),
  ('app-barolo', 'Barolo DOCG', 'Barolo', 'appellation', 'Italy', 'Piedmont', 'Langhe', ARRAY['Barolo', 'Barolo DOCG']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills","cooling_fog_current"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m","new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr","full_bodied_high_abv"],"varietalTraits":["italian_indigenous","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Nebbiolo"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 14, '''King of Wines, Wine of Kings.'' 100% Nebbiolo Requiring 38 months minimum aging (62 for Riserva). Divided between Tortonian calcareous marl (La Morra, Barolo—more perfumed) and older Helvetian/Serravallian sandstone (Serralunga, Monforte—more structured), bottled in the traditional ''Albeisa''.'),
  ('app-barbaresco', 'Barbaresco DOCG', 'Barbaresco', 'appellation', 'Italy', 'Piedmont', 'Langhe', ARRAY['Barbaresco', 'Barbaresco DOCG']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills","cooling_fog_current"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Nebbiolo"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["unesco_landscape"]}'::jsonb, 24, 'Closer to the moderating Tanaro River and slightly lower in altitude than Barolo, allowing 100% Nebbiolo on Tortonian marl (Asili, Rabajà, Martinenga) to ripen slightly earlier with 26 months mandatory aging (50 for Riserva).'),
  ('app-brunello-di-montalcino', 'Brunello di Montalcino DOCG', 'Brunello di Montalcino', 'appellation', 'Italy', 'Tuscany', 'Montalcino (Siena)', ARRAY['Brunello', 'Brunello di Montalcino']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","slate_schist"],"climates":["mediterranean","rain_shadow"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","earthy_truffle_tar","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["italian_indigenous","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Sangiovese"],"bottleShapes":["bordeaux_shoulder"],"heritage":["unesco_landscape"]}'::jsonb, 19, 'Crafted from 100% Sangiovese Grosso (''Brunello'') sheltered by Monte Amiata. Enforces one of the world''s longest aging requirements: 4 years total (5 years for Riserva), including at least 2 years in oak.'),
  ('app-chianti-classico', 'Chianti Classico DOCG', 'Chianti Classico', 'appellation', 'Italy', 'Tuscany', 'Florence & Siena Hills', ARRAY['Chianti Classico', 'Gallo Nero']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","slate_schist","limestone_chalk"],"climates":["mediterranean","continental","diurnal_shift"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar"],"varietalTraits":["italian_indigenous","multi_blend_tradition"],"primaryGrapes":["Sangiovese","Canaiolo","Colorino","Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 17, 'First delimited by Grand Duke Cosimo III de'' Medici in 1716. Minimum 80% Sangiovese grown on friable ''Galestro'' marl-schist and ''Alberese'' limestone, topped by the Gran Selezione tier (minimum 30 months aging, 90%+ Sangiovese).'),
  ('app-bolgheri', 'Bolgheri / Bolgheri Sassicaia DOC', 'Bolgheri', 'appellation', 'Italy', 'Tuscany', 'Maremma Coast', ARRAY['Bolgheri', 'Bolgheri Sassicaia DOC', 'Sassicaia']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO","Super_Tuscan"],"soils":["gravel_alluvial","clay_limestone"],"climates":["mediterranean","maritime"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 26, 'Cradle of the ''Super Tuscan'' revolution along the Tyrrhenian coast, where stony gravel (''sassi'') and sea light mirror Bordeaux''s Left Bank. Bolgheri Sassicaia DOC was the first single-estate DOC in Italy (2013).'),
  ('app-amarone', 'Amarone della Valpolicella DOCG', 'Amarone della Valpolicella', 'appellation', 'Italy', 'Veneto', 'Valpolicella (Verona)', ARRAY['Amarone', 'Amarone della Valpolicella']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DOCG"],"soils":["limestone_chalk","volcanic_basalt","clay_limestone"],"climates":["continental","alpine_foothills"],"waterBodies":[],"styles":["passito_appassimento","dry_red"],"vinification":["large_neutral_botte_foudre","new_french_oak","extended_aging_36m"],"sensory":["full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["italian_indigenous","multi_blend_tradition"],"primaryGrapes":["Corvina","Corvinone","Rondinella"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":[]}'::jsonb, 21, 'Produced via ''Appassimento'': harvested bunches of Corvina, Corvinone, and Rondinella dry for 100–120 days in ventilated ''fruttai'' lofts, losing ~40% of their weight before slow fermentation to dryness (>15% ABV).'),
  ('app-soave-classico', 'Soave Classico DOC', 'Soave Classico', 'appellation', 'Italy', 'Veneto', 'Verona Hills', ARRAY['Soave', 'Soave Classico', 'Soave Superiore DOCG']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["PDO_DO","DOCG"],"soils":["volcanic_basalt","limestone_chalk"],"climates":["continental","alpine_foothills"],"waterBodies":[],"styles":["dry_white","passito_appassimento"],"vinification":["amphora_concrete_unoaked","sur_lie_autolysis"],"sensory":["saline_mineral","laser_high_acid"],"varietalTraits":["italian_indigenous"],"primaryGrapes":["Garganega","Trebbiano di Soave"],"bottleShapes":["burgundy_slope","alsace_flute_schlegel"],"heritage":[]}'::jsonb, 38, 'The historic hillside Classico zone east of Verona features dark Eocene volcanic basalt and tuff where minimum 70% late-ripening Garganega (often trained on traditional Veronese pergolas) develops chamomile, almond, and smoky minerality.'),
  ('app-franciacorta', 'Franciacorta DOCG', 'Franciacorta', 'appellation', 'Italy', 'Lombardy', 'Brescia / Lake Iseo', ARRAY['Franciacorta', 'Franciacorta Satèn']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DOCG"],"soils":["gravel_alluvial","limestone_chalk"],"climates":["continental","alpine_foothills"],"waterBodies":["major_river"],"styles":["sparkling_traditional"],"vinification":["sur_lie_autolysis","extended_aging_36m"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["burgundy_family","multi_blend_tradition"],"primaryGrapes":["Chardonnay","Pinot Noir","Pinot Blanc"],"bottleShapes":["champagne_heavy"],"heritage":[]}'::jsonb, 39, 'Italy''s premier Metodo Classico sparkling wine grown on a glacial moraine amphitheater south of Lake Iseo. Franciacorta Riserva requires an extraordinary 60 months on the lees.'),
  ('app-etna', 'Etna DOC', 'Etna', 'appellation', 'Italy', 'Sicily', 'Mount Etna Contrade', ARRAY['Etna', 'Etna Rosso', 'Etna Bianco']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["volcanic_basalt","sand_phylloxera_free"],"climates":["mediterranean","high_altitude","steep_heroic_slopes","diurnal_shift"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","dry_white"],"vinification":["large_neutral_botte_foudre","amphora_concrete_unoaked"],"sensory":["high_tannin_high_acid","saline_mineral","violet_rose_floral","earthy_truffle_tar"],"varietalTraits":["italian_indigenous"],"primaryGrapes":["Nerello Mascalese","Carricante","Nerello Cappuccio"],"bottleShapes":["burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 27, 'The ''Burgundy of the Mediterranean.'' Terraced dry-stone lava walls up to 1,100m altitude on Europe''s highest active volcano harbor century-old ungrafted alberello vines of Nerello Mascalese and Carricante.'),
  ('app-taurasi', 'Taurasi DOCG', 'Taurasi', 'appellation', 'Italy', 'Campania', 'Irpinia (Avellino)', ARRAY['Taurasi', 'Taurasi DOCG']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["volcanic_basalt","clay_limestone"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","thick_skin_late_ripening"],"primaryGrapes":["Aglianico"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 48, 'Nicknamed the ''Barolo of the South.'' High-altitude Apennine vineyards covered in volcanic ash from ancient Mount Vesuvius eruptions ripen Aglianico as late as November, requiring 36 months minimum aging (48 for Riserva).'),
  ('app-rioja', 'Rioja DOCa', 'Rioja', 'appellation', 'Spain', 'Ebro Valley', 'Rioja Alta / Rioja Alavesa / Rioja Oriental', ARRAY['Rioja', 'Rioja DOCa', 'Rioja Gran Reserva']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCa"],"soils":["clay_limestone","iron_clay","gravel_alluvial"],"climates":["continental","mediterranean","high_altitude","rain_shadow"],"waterBodies":["ebro_duero","major_river"],"styles":["dry_red","dry_white","rose_specialist"],"vinification":["extended_aging_36m","new_french_oak"],"sensory":["earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","multi_blend_tradition"],"primaryGrapes":["Tempranillo","Garnacha","Graciano","Mazuelo","Viura"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines"]}'::jsonb, 14, 'Spain''s first Denominación de Origen Calificada (1991), sheltered by the Sierra de Cantabria. Famous for its strict aging pyramid (Crianza, Reserva, and Gran Reserva requiring 60 months total aging) and classic American & French oak maturation.'),
  ('app-priorat', 'Priorat DOCa (DOQ)', 'Priorat', 'appellation', 'Spain', 'Catalonia', 'Tarragona Hills', ARRAY['Priorat', 'Priorato', 'Priorat DOQ']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCa","Grand_Cru"],"soils":["slate_schist"],"climates":["mediterranean","steep_heroic_slopes","high_altitude"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","saline_mineral","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["rhone_family","iberian_indigenous","multi_blend_tradition"],"primaryGrapes":["Garnacha","Cariñena","Syrah","Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["bush_vines","monastic_origin"]}'::jsonb, 29, 'One of only two DOCa regions in Spain. Centenarian bush vines of Garnacha and Cariñena send roots meters deep into glittering dark Paleozoic ''llicorella'' slate and quartz terraces (''costers''), now classified up to ''Gran Vinya Classificada''.'),
  ('app-ribera-del-duero', 'Ribera del Duero DO', 'Ribera del Duero', 'appellation', 'Spain', 'Castilla y León', 'Northern Meseta', ARRAY['Ribera del Duero']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["PDO_DO"],"soils":["clay_limestone","limestone_chalk","sand_phylloxera_free"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":["ebro_duero","douro_river","major_river"],"styles":["dry_red"],"vinification":["new_french_oak","extended_aging_36m"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","bordeaux_family"],"primaryGrapes":["Tempranillo","Cabernet Sauvignon","Merlot","Albillo Mayor"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 23, 'Situated at 720–1,000+ meters on Spain''s northern plateau, where daytime highs of 38°C drop to 12°C at night. This extreme diurnal shift thickens the skins of Tinto Fino (Tempranillo), producing deeply colored, monumental wines.'),
  ('app-jerez-sherry', 'Jerez-Xérès-Sherry DO', 'Jerez-Xérès-Sherry', 'appellation', 'Spain', 'Andalusia', 'Marco de Jerez (Jerez / Sanlúcar / El Puerto)', ARRAY['Sherry', 'Jerez', 'Xérès', 'Manzanilla-Sanlúcar de Barrameda']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["albariza","limestone_chalk"],"climates":["mediterranean","maritime"],"waterBodies":["atlantic_ocean","major_river"],"styles":["fortified","oxidative_biological","passito_appassimento"],"vinification":["solera_system","flor_yeast","extended_aging_36m"],"sensory":["saline_mineral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","single_varietal_strict"],"primaryGrapes":["Palomino Fino","Pedro Ximénez","Moscatel"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 24, 'Grown on brilliant white diatomaceous ''Albariza'' chalk that forms a moisture-sealing crust in summer. Aged via fractional blending in the Criadera & Solera system, either biologically under a living blanket of ''flor'' yeast (Fino/Manzanilla) or oxidatively (Oloroso).'),
  ('app-rias-baixas', 'Rías Baixas DO', 'Rías Baixas', 'appellation', 'Spain', 'Galicia', 'Val do Salnés / O Rosal', ARRAY['Rias Baixas', 'Rías Baixas']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["granite","sand_phylloxera_free"],"climates":["maritime"],"waterBodies":["atlantic_ocean","major_river"],"styles":["dry_white"],"vinification":["sur_lie_autolysis","amphora_concrete_unoaked"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["iberian_indigenous","aromatic_white","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Albariño"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 26, 'In cool, rain-swept Atlantic Galicia (''Green Spain''), thick-skinned Albariño vines are trained high off the damp decomposed granite soil on granite-post ''parral'' pergolas to maximize wind circulation.'),
  ('app-porto', 'Porto DOC (Douro Valley)', 'Porto / Douro', 'appellation', 'Portugal', 'Douro', 'Baixo Corgo / Cima Corgo / Douro Superior', ARRAY['Port', 'Porto', 'Porto DOC']::text[], '{"countryCode":"PT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["PDO_DO"],"soils":["slate_schist","granite"],"climates":["continental","mediterranean","steep_heroic_slopes","rain_shadow"],"waterBodies":["douro_river","major_river"],"styles":["fortified","dry_red","oxidative_biological"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["full_bodied_high_abv","high_tannin_high_acid","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","multi_blend_tradition","thick_skin_late_ripening"],"primaryGrapes":["Touriga Nacional","Touriga Franca","Tinta Roriz","Tinta Barroca","Tinto Cão"],"bottleShapes":["bordeaux_shoulder","specialty_traditional"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 16, 'Demarcated by the Marquis of Pombal in 1756—one of the world''s oldest protected wine regions. Carved into vertical Pre-Cambrian schist terraces (''socalcos'') along the Douro River and fortified mid-fermentation with 77% ABV ''aguardente''.'),
  ('app-madeira', 'Madeira DOC', 'Madeira', 'appellation', 'Portugal', 'Madeira Island', 'Atlantic Archipelago', ARRAY['Madeira', 'Madeira DOC']::text[], '{"countryCode":"PT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["volcanic_basalt"],"climates":["maritime","steep_heroic_slopes","high_altitude"],"waterBodies":["atlantic_ocean"],"styles":["fortified","oxidative_biological"],"vinification":["extended_aging_36m","large_neutral_botte_foudre"],"sensory":["laser_high_acid","full_bodied_high_abv","long_cellar_20yr","saline_mineral"],"varietalTraits":["iberian_indigenous","single_varietal_strict"],"primaryGrapes":["Sercial","Verdelho","Bual","Malmsey","Tinta Negra"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 40, 'Volcanic island wine rendered virtually immortal through intentional heating (''Canteiro'' in warm attic lofts or ''Estufagem'') and oxidative aging, balancing caramel, roasted walnut, and orange peel with piercing natural acidity.'),
  ('app-mosel', 'Mosel (Prädikatswein / VDP)', 'Mosel', 'appellation', 'Germany', 'Mosel', 'Mittelmosel / Saar / Ruwer', ARRAY['Mosel', 'Mosel-Saar-Ruwer']::text[], '{"countryCode":"DE","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Pradikatswein_VDP","PDO_DO","Grand_Cru"],"soils":["slate_schist"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["laser_high_acid","low_abv_delicate","petrol_tdn","saline_mineral","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["aromatic_white","single_varietal_strict"],"primaryGrapes":["Riesling"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["ungrafted_pre_phylloxera","codified_pre_1855"]}'::jsonb, 16, 'Home to the steepest vineyard in the world (Bremmer Calmont at 65°). Devonian blue and red slate (''Schiefer'') reflects river sunlight and retains heat, allowing Riesling at 50°N to achieve ethereal Kabinett, Spätlese, Auslese, and Trockenbeerenauslese precision on ungrafted vines.'),
  ('app-rheingau', 'Rheingau (Prädikatswein / VDP)', 'Rheingau', 'appellation', 'Germany', 'Rheingau', 'Rüdesheim to Hochheim', ARRAY['Rheingau']::text[], '{"countryCode":"DE","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Pradikatswein_VDP","PDO_DO","Grand_Cru"],"soils":["slate_schist","loess_silt","clay_limestone"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet","dry_red"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["laser_high_acid","petrol_tdn","long_cellar_20yr"],"varietalTraits":["aromatic_white","burgundy_family","single_varietal_strict"],"primaryGrapes":["Riesling","Spätburgunder"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["monastic_origin","codified_pre_1855"]}'::jsonb, 33, 'Where the Rhine abruptly turns west for 30 km beneath the Taunus hills, creating south-facing slopes. Birthplace of Spätlese (1775 at Schloss Johannisberg) and home to the Cistercian monastery Kloster Eberbach.'),
  ('app-wachau', 'Wachau DAC', 'Wachau', 'appellation', 'Austria', 'Niederösterreich (Lower Austria)', 'Danube Gorge', ARRAY['Wachau', 'Wachau DAC']::text[], '{"countryCode":"AT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DAC","PDO_DO"],"soils":["granite","slate_schist","loess_silt"],"climates":["continental","steep_heroic_slopes","diurnal_shift"],"waterBodies":["major_river"],"styles":["dry_white"],"vinification":["large_neutral_botte_foudre","no_malolactic","sur_lie_autolysis"],"sensory":["laser_high_acid","saline_mineral","rotundone_black_pepper","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","aromatic_white"],"primaryGrapes":["Grüner Veltliner","Riesling"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["unesco_landscape","monastic_origin"]}'::jsonb, 35, 'A UNESCO World Heritage Danube valley where cool Waldviertel winds meet warm Pannonian air across primary rock (''Urgestein'' gneiss) and windblown loess terraces. Famous for its dry wine tiers: Steinfeder, Federspiel, and full-bodied Smaragd.'),
  ('app-tokaj', 'Tokaj PDO (Tokaji Aszú)', 'Tokaj', 'appellation', 'Hungary', 'Tokaj-Hegyalja', 'Zemplén Mountains', ARRAY['Tokaj', 'Tokaji', 'Tokaji Aszu']::text[], '{"countryCode":"HU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["PDO_DO","Grand_Cru"],"soils":["volcanic_basalt","loess_silt"],"climates":["continental","cooling_fog_current"],"waterBodies":["major_river"],"styles":["botrytis_sweet","dry_white"],"vinification":["extended_aging_36m","large_neutral_botte_foudre"],"sensory":["honey_saffron_botrytis","laser_high_acid","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","multi_blend_tradition","thin_skin_early_ripening"],"primaryGrapes":["Furmint","Hárslevelű","Sárgamuskotály"],"bottleShapes":["specialty_traditional"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 28, 'The world''s first officially classified vineyard system (Royal Decree of 1737). Autumn mists from the confluence of the Tisza and Bodrog rivers shrivel high-acid Furmint on volcanic rhyolite tuff into ''Aszú'' berries, aged in labyrinthine mold-lined cellars and bottled in the 500ml Tokaji bottle.'),
  ('app-santorini', 'Santorini PDO', 'Santorini', 'appellation', 'Greece', 'Aegean Islands', 'Cyclades', ARRAY['Santorini', 'Santorini Assyrtiko', 'Vinsanto']::text[], '{"countryCode":"GR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["volcanic_basalt","sand_phylloxera_free"],"climates":["mediterranean","cooling_fog_current"],"waterBodies":["mediterranean_sea"],"styles":["dry_white","passito_appassimento"],"vinification":["amphora_concrete_unoaked","sur_lie_autolysis","no_malolactic"],"sensory":["laser_high_acid","saline_mineral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["single_varietal_strict"],"primaryGrapes":["Assyrtiko","Aidani","Athiri"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines","codified_pre_1855"]}'::jsonb, 29, 'Formed by the catastrophic Minoan volcanic eruption (~1600 BCE). Phylloxera cannot survive in the pumice, ash, and lava sand; 200-year-old ungrafted Assyrtiko vines are woven into ground-hugging ''kouloura'' baskets to trap nocturnal sea mist and shield grapes from fierce Meltemi winds.'),
  ('app-naoussa', 'Naoussa PDO', 'Naoussa', 'appellation', 'Greece', 'Macedonia', 'Mount Vermio Foothills', ARRAY['Naoussa', 'Naoussa Xinomavro']::text[], '{"countryCode":"GR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["PDO_DO"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","mediterranean"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre"],"sensory":["high_tannin_high_acid","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["single_varietal_strict"],"primaryGrapes":["Xinomavro"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 54, '100% Xinomavro (''Acid-Black'') on the eastern calcareous slopes of Mount Vermio. Revered by sommeliers for its uncanny structural and aromatic resemblance to Nebbiolo in Barolo (sun-dried tomato, olive tapenade, rose petal, and gripping tannins).'),
  ('app-bekaa-valley', 'Bekaa Valley', 'Bekaa Valley', 'appellation', 'Lebanon', 'Bekaa', 'Mount Lebanon & Anti-Lebanon Plateau', ARRAY['Bekaa Valley', 'Beqaa Valley']::text[], '{"countryCode":"LB","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["gravel_alluvial","limestone_chalk","clay_limestone"],"climates":["mediterranean","high_altitude","diurnal_shift"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","dry_white","rose_specialist"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["bordeaux_family","rhone_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Cinsault","Carignan","Obaideh","Merwah"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 49, 'At 1,000 meters elevation between the Lebanon and Anti-Lebanon mountain ranges, adjacent to the ancient Roman Temple of Bacchus at Baalbek, viticulture here spans over 5,000 years.'),
  ('app-napa-valley', 'Napa Valley AVA', 'Napa Valley', 'appellation', 'United States', 'California', 'North Coast (Oakville / Rutherford / Stags Leap / Howell Mountain)', ARRAY['Napa Valley', 'Napa', 'Oakville AVA', 'Rutherford AVA']::text[], '{"countryCode":"US","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AVA"],"soils":["volcanic_basalt","gravel_alluvial"],"climates":["mediterranean","cooling_fog_current","diurnal_shift"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","burgundy_family","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Chardonnay","Merlot","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":[]}'::jsonb, 12, 'Containing half of the world''s 12 soil orders within 30 miles—from alluvial Rutherford bench fans to volcanic Vaca and Mayacamas mountain bedrock—cooled by San Pablo Bay marine fog and catapulted to global fame at the 1976 Judgment of Paris.'),
  ('app-sonoma-coast', 'Sonoma Coast / Russian River Valley AVA', 'Sonoma Coast', 'appellation', 'United States', 'California', 'Sonoma County', ARRAY['Sonoma Coast', 'Russian River Valley', 'Sonoma']::text[], '{"countryCode":"US","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AVA"],"soils":["gravel_alluvial","volcanic_basalt"],"climates":["maritime","cooling_fog_current"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red","dry_white","sparkling_traditional"],"vinification":["new_french_oak","sur_lie_autolysis"],"sensory":["low_tannin_delicate","laser_high_acid","violet_rose_floral"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Pinot Noir","Chardonnay","Zinfandel"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines"]}'::jsonb, 24, 'Cold Pacific upwelling draws dense marine fog through the Petaluma Gap across Goldridge sandy loam soils, creating an ideal cool-climate sanctuary for Pinot Noir and Chardonnay.'),
  ('app-willamette-valley', 'Willamette Valley AVA', 'Willamette Valley', 'appellation', 'United States', 'Oregon', 'Dundee Hills / Eola-Amity Hills / Ribbon Ridge', ARRAY['Willamette Valley', 'Dundee Hills AVA']::text[], '{"countryCode":"US","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AVA"],"soils":["volcanic_basalt","loess_silt"],"climates":["maritime","cooling_fog_current","rain_shadow"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red","dry_white","sparkling_traditional"],"vinification":["new_french_oak","carbonic_whole_cluster"],"sensory":["low_tannin_delicate","laser_high_acid","earthy_truffle_tar","violet_rose_floral"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Pinot Noir","Chardonnay","Pinot Gris"],"bottleShapes":["burgundy_slope"],"heritage":["biodynamic_pioneer"]}'::jsonb, 22, 'At a similar latitude to Burgundy (about 45°N here, about 47°N in the Côte d''Or) and on the 45th parallel with Bordeaux, sheltered by the Coast Range and cooled by afternoon Van Duzer Corridor winds. Defined by two ancient soils: iron-rich red volcanic ''Jory'' basalt and marine sedimentary ''Willakenzie''.'),
  ('app-barossa-valley', 'Barossa Valley GI', 'Barossa Valley', 'appellation', 'Australia', 'South Australia', 'Barossa & Eden Valley', ARRAY['Barossa', 'Barossa Valley']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["sand_phylloxera_free","iron_clay","clay_limestone"],"climates":["mediterranean","continental"],"waterBodies":[],"styles":["dry_red","fortified"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","rotundone_black_pepper","long_cellar_20yr"],"varietalTraits":["rhone_family","bordeaux_family","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Shiraz","Grenache","Mataro (Mourvèdre)","Cabernet Sauvignon"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines","codified_pre_1855"]}'::jsonb, 18, 'Because South Australia enforces strict quarantine and sandy soils, the Barossa Valley possesses the oldest continuously producing ungrafted Shiraz (1843), Grenache, and Mourvèdre bush vines on Earth.'),
  ('app-coonawarra', 'Coonawarra GI', 'Coonawarra', 'appellation', 'Australia', 'South Australia', 'Limestone Coast', ARRAY['Coonawarra']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["GI"],"soils":["terra_rossa","limestone_chalk"],"climates":["maritime","cooling_fog_current"],"waterBodies":["pacific_ocean"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","rhone_family","single_varietal_strict"],"primaryGrapes":["Cabernet Sauvignon","Shiraz"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 30, 'World-famous for its cigar-shaped 15 km ridge of vivid red ''Terra Rossa'' iron-oxide topsoil over porous white marine limestone, cooled by Southern Ocean upwelling and yielding Cabernet Sauvignon with unmistakable eucalyptus and cassis notes.'),
  ('app-clare-eden-valley', 'Clare & Eden Valley GI', 'Clare Valley', 'appellation', 'Australia', 'South Australia', 'Mount Lofty Ranges (Watervale / Polish Hill)', ARRAY['Clare Valley', 'Eden Valley']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["terra_rossa","limestone_chalk","slate_schist"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_white","dry_red"],"vinification":["amphora_concrete_unoaked","no_malolactic"],"sensory":["laser_high_acid","petrol_tdn","saline_mineral","long_cellar_20yr"],"varietalTraits":["aromatic_white","rhone_family","single_varietal_strict"],"primaryGrapes":["Riesling","Shiraz"],"bottleShapes":["alsace_flute_schlegel","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 33, 'High-altitude South Australian valleys (400–550m) where Watervale red loam over limestone and Polish Hill slate produce bone-dry, lime-and-kerosene Rieslings that age effortlessly for decades under screwcap.'),
  ('app-margaret-river', 'Margaret River GI', 'Margaret River', 'appellation', 'Australia', 'Western Australia', 'South West Australia', ARRAY['Margaret River']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["GI"],"soils":["gravel_alluvial","granite"],"climates":["maritime","mediterranean"],"waterBodies":["pacific_ocean"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","sur_lie_autolysis"],"sensory":["high_tannin_high_acid","laser_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","burgundy_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Chardonnay","Sauvignon Blanc","Sémillon"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 31, 'Surrounded on three sides by the Indian and Southern Oceans, with ancient ironstone gravel (''forest grove'') over granite. Produces less than 3% of Australia''s wine volume but over 20% of its super-premium Cabernet and Gin Gin clone Chardonnay.'),
  ('app-marlborough', 'Marlborough GI', 'Marlborough', 'appellation', 'New Zealand', 'South Island', 'Wairau & Awatere Valleys', ARRAY['Marlborough']::text[], '{"countryCode":"NZ","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["GI"],"soils":["gravel_alluvial","loess_silt"],"climates":["maritime","diurnal_shift","rain_shadow"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_white","dry_red","sparkling_traditional"],"vinification":["amphora_concrete_unoaked","no_malolactic"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["bordeaux_family","burgundy_family","aromatic_white","single_varietal_strict"],"primaryGrapes":["Sauvignon Blanc","Pinot Noir","Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 14, 'Free-draining greywacke river gravels and high UV light combined with crisp South Island nights maximize thiol precursors in Sauvignon Blanc, yielding explosive passionfruit, gooseberry, and crushed nettle aromatics.'),
  ('app-central-otago', 'Central Otago GI', 'Central Otago', 'appellation', 'New Zealand', 'South Island', 'Bannockburn / Gibbston / Bendigo', ARRAY['Central Otago']::text[], '{"countryCode":"NZ","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["GI"],"soils":["slate_schist","loess_silt","gravel_alluvial"],"climates":["continental","alpine_foothills","high_altitude","diurnal_shift","steep_heroic_slopes"],"waterBodies":["major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","carbonic_whole_cluster"],"sensory":["low_tannin_delicate","laser_high_acid","violet_rose_floral"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Pinot Noir","Riesling","Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":["biodynamic_pioneer"]}'::jsonb, 29, 'At 45°S latitude inside the Southern Alps rain shadow, Central Otago is New Zealand''s only true continental wine region and one of the world''s southernmost commercial Pinot Noir regions, planted on glittering mica-schist and glacial loess.'),
  ('app-mendoza', 'Mendoza / Uco Valley GI', 'Mendoza', 'appellation', 'Argentina', 'Cuyo', 'Uco Valley (Gualtallary / Paraje Altamira) & Luján de Cuyo', ARRAY['Mendoza', 'Uco Valley', 'Gualtallary', 'Luján de Cuyo']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["gravel_alluvial","limestone_chalk","sand_phylloxera_free"],"climates":["continental","high_altitude","rain_shadow","diurnal_shift","alpine_foothills"],"waterBodies":["major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","amphora_concrete_unoaked"],"sensory":["full_bodied_high_abv","violet_rose_floral","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","single_varietal_strict"],"primaryGrapes":["Malbec","Cabernet Franc","Cabernet Sauvignon","Chardonnay"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 15, 'Andean desert foothills from 900m to 1,600m+ altitude irrigated by snowmelt. High-altitude UV radiation triggers thick, resveratrol-rich skins and floral violet aromatics in Malbec on calcium-carbonate-coated alluvial boulders.'),
  ('app-maipo-colchagua', 'Maipo & Colchagua Valley DO', 'Maipo Valley', 'appellation', 'Chile', 'Central Valley', 'Puente Alto / Apalta', ARRAY['Maipo Valley', 'Colchagua Valley', 'Puente Alto', 'Apalta']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["gravel_alluvial","granite"],"climates":["mediterranean","high_altitude","cooling_fog_current","diurnal_shift"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Carménère","Syrah"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 24, 'Ringed by the Andes, Pacific Ocean (Humboldt Current), Atacama Desert, and Antarctica, Chile has remained completely phylloxera-free. Alluvial gravels of Puente Alto (Maipo) and granitic horseshoe slopes of Apalta (Colchagua) excel with ungrafted Cabernet Sauvignon and Carménère.'),
  ('app-stellenbosch', 'Stellenbosch WO', 'Stellenbosch', 'appellation', 'South Africa', 'Coastal Region', 'Simonsberg / Helderberg / Banghoek', ARRAY['Stellenbosch']::text[], '{"countryCode":"ZA","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["GI"],"soils":["granite","slate_schist"],"climates":["mediterranean","cooling_fog_current"],"waterBodies":["atlantic_ocean"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","sur_lie_autolysis"],"sensory":["full_bodied_high_abv","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Chenin Blanc","Pinotage","Syrah"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["bush_vines","codified_pre_1855"]}'::jsonb, 25, 'Planted on some of Earth''s oldest decomposed granite and Malmesbury shale (~600 million years old), cooled by afternoon ''Cape Doctor'' breezes blowing off False Bay and the icy Benguela Current.'),
  ('grape-cabernet-sauvignon', 'Cabernet Sauvignon (Grape)', 'Cabernet Sauvignon', 'grape', 'France', 'Bordeaux', 'Médoc / Napa Valley / Coonawarra / Maipo', ARRAY['Cabernet Sauvignon', 'Cabernet']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["United States","Chile","Australia"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","First_Growth_1855","AVA"],"soils":["gravel_alluvial","terra_rossa","volcanic_basalt"],"climates":["maritime","mediterranean"],"waterBodies":["gironde_estuary","atlantic_ocean","pacific_ocean"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","parent_cab_franc_sauv_blanc","thick_skin_late_ripening","multi_blend_tradition","single_varietal_strict"],"primaryGrapes":["Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 8, 'Proven by 1997 UC Davis DNA profiling to be a natural 17th-century crossing of Cabernet Franc × Sauvignon Blanc. Small berries with thick, dark skins give high phenolics, cassis, cedar, and methoxypyrazine notes.'),
  ('grape-merlot', 'Merlot (Grape)', 'Merlot', 'grape', 'France', 'Bordeaux', 'Pomerol & Saint-Émilion', ARRAY['Merlot']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","Grand_Cru"],"soils":["iron_clay","clay_limestone"],"climates":["maritime","mediterranean"],"waterBodies":["gironde_estuary","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["bordeaux_family","thin_skin_early_ripening","multi_blend_tradition"],"primaryGrapes":["Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 10, 'Named after the ''merle'' (blackbird) that loves its early-ripening, thin-skinned berries. Offspring of Cabernet Franc × Magdeleine Noire des Charentes, thriving on cool moisture-retaining clay and limestone.'),
  ('grape-cabernet-franc', 'Cabernet Franc (Grape)', 'Cabernet Franc', 'grape', 'France', 'Loire Valley', 'Chinon / Bourgueil / Saint-Émilion', ARRAY['Cabernet Franc', 'Breton', 'Bouchet']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":["Bordeaux"],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru","Autochthonous_Grape"],"soils":["tuffeau","limestone_chalk","gravel_alluvial","clay_limestone"],"climates":["maritime","continental"],"waterBodies":["loire_river","gironde_estuary","major_river"],"styles":["dry_red","rose_specialist"],"vinification":["large_neutral_botte_foudre","new_french_oak","amphora_concrete_unoaked"],"sensory":["laser_high_acid","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["bordeaux_family","thin_skin_early_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Cabernet Franc"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["unesco_landscape","monastic_origin"]}'::jsonb, 20, 'The ancient Basque/Pyrenean parent of Cabernet Sauvignon, Merlot, and Carménère. Known as ''Breton'' in the Loire (where it thrives on yellow tuffeau chalk) and ''Bouchet'' in Saint-Émilion (where it stars at Château Cheval Blanc and Ausone).'),
  ('grape-pinot-noir', 'Pinot Noir (Grape)', 'Pinot Noir', 'grape', 'France', 'Burgundy', 'Côte d''Or / Champagne / Willamette / Central Otago', ARRAY['Pinot Noir', 'Spätburgunder', 'Pinot Nero', 'Blauburgunder']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["United States","New Zealand","Germany"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","Grand_Cru","AVA"],"soils":["clay_limestone","limestone_chalk","volcanic_basalt","slate_schist"],"climates":["continental","maritime","cooling_fog_current"],"waterBodies":["major_river"],"styles":["dry_red","sparkling_traditional","rose_specialist"],"vinification":["new_french_oak","carbonic_whole_cluster","sur_lie_autolysis"],"sensory":["low_tannin_delicate","laser_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["burgundy_family","thin_skin_early_ripening","single_varietal_strict"],"primaryGrapes":["Pinot Noir"],"bottleShapes":["burgundy_slope","champagne_heavy"],"heritage":["monastic_origin","unesco_landscape","codified_pre_1855","biodynamic_pioneer"]}'::jsonb, 9, 'The ''heartbreak grape''—genetically ancient and prone to clonal mutation (Pinot Gris, Pinot Blanc, Pinot Meunier). Its thin skin yields pale ruby color, low tannins, red cherry, rose petal, and forest floor (''sous-bois'') complexity.'),
  ('grape-chardonnay', 'Chardonnay (Grape)', 'Chardonnay', 'grape', 'France', 'Burgundy', 'Côte de Beaune / Chablis / Champagne / Sonoma', ARRAY['Chardonnay', 'Morillon', 'Beaunois']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["United States","New Zealand","Australia"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","Grand_Cru","AVA"],"soils":["kimmeridgian_marl","limestone_chalk","clay_limestone"],"climates":["continental","maritime","cooling_fog_current"],"waterBodies":["major_river"],"styles":["dry_white","sparkling_traditional"],"vinification":["new_french_oak","sur_lie_autolysis","amphora_concrete_unoaked"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","parent_pinot_gouais","single_varietal_strict"],"primaryGrapes":["Chardonnay"],"bottleShapes":["burgundy_slope","champagne_heavy"],"heritage":["monastic_origin","unesco_landscape"]}'::jsonb, 8, 'A natural medieval crossing of Pinot × Gouais Blanc in Burgundy. The ultimate ''winemaker''s canvas'' and terroir translator—expressing steely oyster-shell austerity in Chablis, toasted hazelnut opulence in Meursault, and chalky finesse in Blanc de Blancs Champagne.'),
  ('grape-sauvignon-blanc', 'Sauvignon Blanc (Grape)', 'Sauvignon Blanc', 'grape', 'France', 'Loire Valley', 'Sancerre / Pouilly-Fumé / Bordeaux / Marlborough', ARRAY['Sauvignon Blanc', 'Blanc Fumé', 'Fumé Blanc']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["New Zealand","Australia"],"alsoRegions":["Bordeaux"],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","GI"],"soils":["kimmeridgian_marl","limestone_chalk","gravel_alluvial"],"climates":["continental","maritime","diurnal_shift"],"waterBodies":["loire_river","gironde_estuary","pacific_ocean","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["amphora_concrete_unoaked","no_malolactic","new_french_oak"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["bordeaux_family","aromatic_white","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Sauvignon Blanc"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":[]}'::jsonb, 10, 'Driven by volatile thiols (passionfruit, grapefruit, boxwood) and methoxypyrazines (cut grass, green bell pepper, jalapeno). Parent of Cabernet Sauvignon alongside Cabernet Franc.'),
  ('grape-riesling', 'Riesling (Grape)', 'Riesling', 'grape', 'Germany', 'Mosel', 'Mosel / Rheingau / Alsace / Wachau / Clare Valley', ARRAY['Riesling', 'Rheinriesling', 'Johannisberg Riesling']::text[], '{"countryCode":"DE","originCountries":[],"alsoCountries":["Australia","France"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","Pradikatswein_VDP","Grand_Cru","AOC","DAC"],"soils":["slate_schist","granite","limestone_chalk","terra_rossa"],"climates":["continental","steep_heroic_slopes","rain_shadow"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic","amphora_concrete_unoaked"],"sensory":["laser_high_acid","petrol_tdn","saline_mineral","honey_saffron_botrytis","low_abv_delicate","long_cellar_20yr"],"varietalTraits":["aromatic_white","single_varietal_strict"],"primaryGrapes":["Riesling"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["ungrafted_pre_phylloxera","codified_pre_1855","monastic_origin"]}'::jsonb, 11, 'First documented at Rüsselsheim, near the Rheingau, on 13 March 1435. Famous for developing the aromatic compound TDN (1,1,6-trimethyl-1,2-dihydronaphthalene), which gives aged Riesling its signature kerosene/petrol note alongside electric acidity.'),
  ('grape-syrah', 'Syrah / Shiraz (Grape)', 'Syrah', 'grape', 'France', 'Rhône Valley', 'Côte-Rôtie / Hermitage / Barossa / Hawke''s Bay', ARRAY['Syrah', 'Shiraz']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["Australia"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Noble_Grape","AOC","GI"],"soils":["granite","slate_schist","sand_phylloxera_free"],"climates":["continental","mediterranean","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red"],"vinification":["co_fermentation","new_french_oak","carbonic_whole_cluster","large_neutral_botte_foudre"],"sensory":["rotundone_black_pepper","violet_rose_floral","full_bodied_high_abv","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["rhone_family","thick_skin_late_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Syrah"],"bottleShapes":["burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","codified_pre_1855"]}'::jsonb, 11, 'Offspring of two obscure southeastern French grapes: Dureza × Mondeuse Blanche. Rich in the sesquiterpene ''rotundone'', which imparts unmistakable cracked black pepper, smoked meat, black olive, and violet notes.'),
  ('grape-nebbiolo', 'Nebbiolo (Grape)', 'Nebbiolo', 'grape', 'Italy', 'Piedmont', 'Barolo / Barbaresco / Roero / Valtellina (Chiavennasca)', ARRAY['Nebbiolo', 'Spanna', 'Chiavennasca', 'Picotendro']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG","Autochthonous_Grape"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills","cooling_fog_current","steep_heroic_slopes"],"waterBodies":["major_river"],"styles":["dry_red","passito_appassimento"],"vinification":["large_neutral_botte_foudre","extended_aging_36m","new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr","full_bodied_high_abv"],"varietalTraits":["italian_indigenous","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Nebbiolo"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 16, 'Named after ''nebbia'' (autumn morning fog in the Langhe). Deceptively pale brick-garnet in the glass due to unstable peonidin anthocyanins, yet packing ferocious tannins, searing acidity, and haunting aromas of tar, white truffle, and dried roses.'),
  ('grape-sangiovese', 'Sangiovese (Grape)', 'Sangiovese', 'grape', 'Italy', 'Tuscany', 'Chianti Classico / Montalcino / Montepulciano', ARRAY['Sangiovese', 'Brunello', 'Prugnolo Gentile', 'Morellino', 'Nielluccio']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG","Autochthonous_Grape","Super_Tuscan"],"soils":["clay_limestone","slate_schist","limestone_chalk"],"climates":["mediterranean","diurnal_shift"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","passito_appassimento"],"vinification":["large_neutral_botte_foudre","extended_aging_36m","new_french_oak"],"sensory":["high_tannin_high_acid","earthy_truffle_tar","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["italian_indigenous","thin_skin_early_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Sangiovese"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855","unesco_landscape"]}'::jsonb, 15, 'Italy''s most widely planted red grape (''Sanguis Jovis''—Blood of Jupiter). High natural acidity and firm tannins deliver sour Marasca cherry, dried oregano, leather, and terracotta nuances.'),
  ('grape-tempranillo', 'Tempranillo (Grape)', 'Tempranillo', 'grape', 'Spain', 'Ebro Valley', 'Rioja / Ribera del Duero / Toro / Douro', ARRAY['Tempranillo', 'Tinto Fino', 'Tinta del País', 'Tinta de Toro', 'Tinta Roriz', 'Cencibel', 'Aragonez', 'Ull de Llebre']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":["Portugal"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCa","PDO_DO","Autochthonous_Grape"],"soils":["clay_limestone","limestone_chalk","iron_clay"],"climates":["continental","high_altitude","diurnal_shift","rain_shadow"],"waterBodies":["ebro_duero","douro_river","major_river"],"styles":["dry_red","fortified"],"vinification":["extended_aging_36m","new_french_oak"],"sensory":["earthy_truffle_tar","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","multi_blend_tradition","single_varietal_strict"],"primaryGrapes":["Tempranillo"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 15, 'From ''temprano'' (early), ripening two weeks before Garnacha. Needs high-altitude chalk/clay and cool nights to preserve acidity, absorbing oak aging effortlessly to yield tobacco leaf, dill, fig, and leather.'),
  ('grape-grenache', 'Grenache / Garnacha (Grape)', 'Grenache', 'grape', 'Spain', 'Aragon', 'Châteauneuf-du-Pape / Priorat / Barossa / Sardinia (Cannonau)', ARRAY['Grenache', 'Garnacha', 'Garnatxa', 'Grenache Noir', 'Cannonau', 'Garnacha Tinta']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":["France","Australia"],"alsoRegions":["Rhône Valley","Provence"],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC","DOCa","Autochthonous_Grape"],"soils":["galets_roules","slate_schist","sand_phylloxera_free"],"climates":["mediterranean","steep_heroic_slopes","high_altitude"],"waterBodies":["rhone_river","mediterranean_sea"],"styles":["dry_red","rose_specialist","fortified"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster","amphora_concrete_unoaked"],"sensory":["full_bodied_high_abv","low_tannin_delicate","long_cellar_20yr"],"varietalTraits":["rhone_family","iberian_indigenous","thin_skin_early_ripening","multi_blend_tradition"],"primaryGrapes":["Grenache"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 16, 'Drought-resistant Mediterranean workhorse with upright wood ideally suited to gobelet bush training. Accumulates high sugar (often 14.5–16% ABV) with translucent ruby color, kirsch, white pepper, and garrigue herbs.'),
  ('grape-chenin-blanc', 'Chenin Blanc (Grape)', 'Chenin Blanc', 'grape', 'France', 'Loire Valley', 'Vouvray / Savennières / Quarts de Chaume / Stellenbosch / Swartland', ARRAY['Chenin Blanc', 'Pineau de la Loire', 'Steen']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["South Africa"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru","Autochthonous_Grape","GI"],"soils":["tuffeau","slate_schist","granite"],"climates":["maritime","continental","mediterranean"],"waterBodies":["loire_river","atlantic_ocean","major_river"],"styles":["dry_white","sparkling_traditional","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic","sur_lie_autolysis"],"sensory":["laser_high_acid","honey_saffron_botrytis","saline_mineral","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Chenin Blanc"],"bottleShapes":["burgundy_slope","champagne_heavy"],"heritage":["biodynamic_pioneer","monastic_origin","bush_vines"]}'::jsonb, 21, 'Perhaps the world''s most versatile white grape—producing bone-dry Savennières, Traditional Method Crémant/Vouvray Pétillant, and immortal botrytized Quarts de Chaume with trademark quince, lanolin, chamomile, and baked apple.'),
  ('grape-assyrtiko', 'Assyrtiko (Grape)', 'Assyrtiko', 'grape', 'Greece', 'Aegean Islands', 'Santorini', ARRAY['Assyrtiko']::text[], '{"countryCode":"GR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["volcanic_basalt","sand_phylloxera_free"],"climates":["mediterranean","cooling_fog_current"],"waterBodies":["mediterranean_sea"],"styles":["dry_white","passito_appassimento"],"vinification":["amphora_concrete_unoaked","sur_lie_autolysis","no_malolactic"],"sensory":["laser_high_acid","saline_mineral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["single_varietal_strict"],"primaryGrapes":["Assyrtiko"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines","codified_pre_1855"]}'::jsonb, 32, 'A rare biological marvel among white grapes: even under scorching Mediterranean sun at 14.5% ABV, Assyrtiko retains a pH below 3.0 and total acidity above 7–8 g/L, delivering volcanic pumice smoke and sea salt.'),
  ('grape-furmint', 'Furmint (Grape)', 'Furmint', 'grape', 'Hungary', 'Tokaj-Hegyalja', 'Tokaj / Somló', ARRAY['Furmint', 'Mosler', 'Šipon']::text[], '{"countryCode":"HU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["PDO_DO","Grand_Cru","Autochthonous_Grape"],"soils":["volcanic_basalt","loess_silt"],"climates":["continental","cooling_fog_current"],"waterBodies":["major_river"],"styles":["botrytis_sweet","dry_white"],"vinification":["extended_aging_36m","large_neutral_botte_foudre"],"sensory":["laser_high_acid","honey_saffron_botrytis","saline_mineral","long_cellar_20yr"],"varietalTraits":["parent_pinot_gouais","thin_skin_early_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Furmint"],"bottleShapes":["specialty_traditional","burgundy_slope"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 36, 'Offspring of Gouais Blanc (making it a half-sibling of Chardonnay and Riesling). Its thin skin and loose bunches invite Botrytis cinerea for Tokaji Aszú while maintaining searing, electric lime-and-apricot acidity.'),
  ('grape-gruner-veltliner', 'Grüner Veltliner (Grape)', 'Grüner Veltliner', 'grape', 'Austria', 'Niederösterreich (Lower Austria)', 'Wachau / Kamptal / Kremstal / Weinviertel', ARRAY['Gruner Veltliner', 'Grüner Veltliner', 'GruVe', 'Weißgipfler']::text[], '{"countryCode":"AT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DAC","PDO_DO","Autochthonous_Grape"],"soils":["loess_silt","granite","slate_schist"],"climates":["continental","steep_heroic_slopes","diurnal_shift"],"waterBodies":["major_river"],"styles":["dry_white"],"vinification":["large_neutral_botte_foudre","no_malolactic","sur_lie_autolysis"],"sensory":["laser_high_acid","rotundone_black_pepper","saline_mineral","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","aromatic_white"],"primaryGrapes":["Grüner Veltliner"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["unesco_landscape","monastic_origin"]}'::jsonb, 28, 'Austria''s flagship autochthonous white grape (Savagnin × St. Georgen-Rebe). Uniquely among white varieties, it contains high levels of rotundone, giving its signature white pepper, lentil, and radish snap.'),
  ('grape-malbec', 'Malbec / Côt (Grape)', 'Malbec', 'grape', 'Argentina', 'Cuyo', 'Mendoza (Uco Valley / Luján) & Cahors AOC', ARRAY['Malbec', 'Côt', 'Auxerrois (Cahors)']::text[], '{"countryCode":"AR","originCountries":["France"],"alsoCountries":["France"],"alsoRegions":["Bordeaux"],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI","AOC","Noble_Grape"],"soils":["gravel_alluvial","limestone_chalk","clay_limestone"],"climates":["continental","high_altitude","diurnal_shift","rain_shadow"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak","amphora_concrete_unoaked"],"sensory":["full_bodied_high_abv","violet_rose_floral","high_tannin_high_acid"],"varietalTraits":["bordeaux_family","thick_skin_late_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Malbec"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 14, 'Originating in Southwest France (Cahors) as an offspring of Prunelard × Magdeleine Noire des Charentes (making it a half-sibling of Merlot), then brought to Mendoza in 1853 by French agronomist Michel Pouget.'),
  ('grape-gamay', 'Gamay Noir (Grape)', 'Gamay', 'grape', 'France', 'Burgundy', 'Beaujolais Crus (Morgon / Moulin-à-Vent / Fleurie)', ARRAY['Gamay', 'Gamay Noir à Jus Blanc']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Autochthonous_Grape"],"soils":["granite","slate_schist","volcanic_basalt"],"climates":["continental"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["carbonic_whole_cluster","large_neutral_botte_foudre"],"sensory":["low_tannin_delicate","laser_high_acid","violet_rose_floral"],"varietalTraits":["burgundy_family","parent_pinot_gouais","thin_skin_early_ripening","single_varietal_strict"],"primaryGrapes":["Gamay"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","biodynamic_pioneer"]}'::jsonb, 24, 'Banished from the Côte d''Or in 1395 by Duke Philip the Bold as ''disloyal'', yet thriving on the pink granite and manganese schist of the 10 Beaujolais Crus via whole-cluster semi-carbonic maceration.'),
  ('grape-albarino', 'Albariño / Alvarinho (Grape)', 'Albariño', 'grape', 'Spain', 'Galicia', 'Rías Baixas & Monção e Melgaço (Vinho Verde)', ARRAY['Albarino', 'Albariño', 'Alvarinho']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":["Portugal"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["granite","sand_phylloxera_free"],"climates":["maritime"],"waterBodies":["atlantic_ocean","major_river"],"styles":["dry_white"],"vinification":["sur_lie_autolysis","amphora_concrete_unoaked","no_malolactic"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["iberian_indigenous","aromatic_white","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Albariño"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 25, 'Thick skins resist Botrytis in damp Atlantic coastal Galicia and Minho, while terpene compounds deliver white peach, apricot kernel, grapefruit pith, and sea-breeze salinity.'),
  ('grape-viognier', 'Viognier (Grape)', 'Viognier', 'grape', 'France', 'Rhône Valley', 'Condrieu / Château-Grillet / Côte-Rôtie', ARRAY['Viognier']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Autochthonous_Grape"],"soils":["granite","slate_schist"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_white"],"vinification":["new_french_oak","co_fermentation","sur_lie_autolysis"],"sensory":["full_bodied_high_abv","violet_rose_floral"],"varietalTraits":["rhone_family","aromatic_white","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Viognier"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 27, 'Down to about 8 ha (about 20 acres) worldwide in 1965 in Condrieu and Château-Grillet before its global renaissance. Famous for opulent apricot, honeysuckle, and violet aromatics and for co-fermenting with Syrah in Côte-Rôtie to stabilize color via copigmentation.'),
  ('grape-touriga-nacional', 'Touriga Nacional (Grape)', 'Touriga Nacional', 'grape', 'Portugal', 'Douro', 'Douro Valley & Dão', ARRAY['Touriga Nacional']::text[], '{"countryCode":"PT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["slate_schist","granite"],"climates":["continental","mediterranean","steep_heroic_slopes"],"waterBodies":["douro_river","major_river"],"styles":["fortified","dry_red"],"vinification":["new_french_oak","large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","violet_rose_floral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","thick_skin_late_ripening","multi_blend_tradition","single_varietal_strict"],"primaryGrapes":["Touriga Nacional"],"bottleShapes":["bordeaux_shoulder"],"heritage":["unesco_landscape","codified_pre_1855"]}'::jsonb, 33, 'Portugal''s flagship red grape: tiny, thick-skinned berries yield low juice-to-skin ratios packed with deep color, firm tannins, and bergamot, rockrose (''esteva''), blueberry, and wild violet aromas.'),
  ('grape-nerello-mascalese', 'Nerello Mascalese (Grape)', 'Nerello Mascalese', 'grape', 'Italy', 'Sicily', 'Mount Etna', ARRAY['Nerello Mascalese']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["volcanic_basalt","sand_phylloxera_free"],"climates":["mediterranean","high_altitude","steep_heroic_slopes","diurnal_shift"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","amphora_concrete_unoaked"],"sensory":["high_tannin_high_acid","saline_mineral","violet_rose_floral","earthy_truffle_tar"],"varietalTraits":["italian_indigenous","thick_skin_late_ripening"],"primaryGrapes":["Nerello Mascalese"],"bottleShapes":["burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 35, 'Named after the Mascali plain on Mount Etna, and genetically an offspring of Sangiovese. Combines the translucent ruby hue and red-fruited perfume of Pinot Noir with the tannic grip and ferrous volcanic snap of Nebbiolo.'),
  ('grape-palomino-fino', 'Palomino Fino (Grape)', 'Palomino Fino', 'grape', 'Spain', 'Andalusia', 'Marco de Jerez / Sanlúcar de Barrameda', ARRAY['Palomino', 'Palomino Fino', 'Listán Blanco']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["PDO_DO","Autochthonous_Grape"],"soils":["albariza","limestone_chalk","volcanic_basalt"],"climates":["mediterranean","maritime"],"waterBodies":["atlantic_ocean"],"styles":["fortified","oxidative_biological","dry_white"],"vinification":["solera_system","flor_yeast","extended_aging_36m"],"sensory":["saline_mineral","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","single_varietal_strict"],"primaryGrapes":["Palomino Fino"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","codified_pre_1855"]}'::jsonb, 41, 'Deliberately neutral in primary fruit and low in acidity so that chalky Albariza terroir, biological ''flor'' yeast acetaldehydes, and Solera fractional aging shine unhindered in Fino, Manzanilla, Amontillado, and Oloroso Sherry.'),
  ('grape-savagnin', 'Savagnin / Traminer (Grape)', 'Savagnin', 'grape', 'France', 'Jura', 'Château-Chalon / Arbois / Côtes du Jura', ARRAY['Savagnin', 'Naturé', 'Traminer', 'Heida', 'Païen']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Autochthonous_Grape"],"soils":["clay_limestone","kimmeridgian_marl"],"climates":["continental","steep_heroic_slopes"],"waterBodies":[],"styles":["oxidative_biological","dry_white"],"vinification":["flor_yeast","extended_aging_36m","large_neutral_botte_foudre"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Savagnin"],"bottleShapes":["specialty_traditional","burgundy_slope"],"heritage":["monastic_origin","biodynamic_pioneer"]}'::jsonb, 47, 'One of Europe''s oldest patriarch grapes (parent of Sauvignon Blanc, Chenin Blanc, and Grüner Veltliner, and the non-aromatic form of the Traminer family, of which Gewürztraminer is a mutation). Powers Jura''s biologically aged Vin Jaune (''sous voile'') and topped-up ''ouillé'' whites.'),
  ('prod-drc', 'Domaine de la Romanée-Conti (DRC)', 'Domaine de la Romanée-Conti', 'producer', 'France', 'Burgundy', 'Vosne-Romanée (Côte de Nuits)', ARRAY['DRC', 'Romanee-Conti', 'Domaine de la Romanée-Conti', 'La Tâche']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","carbonic_whole_cluster"],"sensory":["low_tannin_delicate","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Pinot Noir","Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin","unesco_landscape","biodynamic_pioneer","codified_pre_1855"]}'::jsonb, 16, 'Burgundy''s pinnacle estate, farming exclusively Grand Cru vineyards including the iconic monopoles Romanée-Conti (1.81 ha) and La Tâche (6.06 ha) using biodynamic viticulture and whole-cluster fermentation.'),
  ('prod-chateau-lafite', 'Château Lafite Rothschild', 'Château Lafite Rothschild', 'producer', 'France', 'Bordeaux', 'Pauillac AOC (Left Bank)', ARRAY['Lafite', 'Chateau Lafite Rothschild', 'Château Lafite']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855","Grand_Cru"],"soils":["gravel_alluvial","limestone_chalk"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 17, 'Ranked first among the Premier Crus in the 1855 Classification of the Médoc. Its deep windblown gravel over tertiary limestone plateau in northern Pauillac produces the most perfumed, cedar-and-graphite-scented First Growth.'),
  ('prod-chateau-margaux', 'Château Margaux', 'Château Margaux', 'producer', 'France', 'Bordeaux', 'Margaux AOC (Left Bank)', ARRAY['Chateau Margaux', 'Château Margaux', 'Pavillon Blanc']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855","Grand_Cru"],"soils":["gravel_alluvial"],"climates":["maritime"],"waterBodies":["gironde_estuary","atlantic_ocean","major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Petit Verdot","Cabernet Franc","Sauvignon Blanc"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 18, 'The only 1855 First Growth sharing its name with its commune AOC. Celebrated for combining iron-fist Cabernet Sauvignon structure with silky violet aromatics on white Pyrenean gravel, plus 100% Sauvignon Blanc ''Pavillon Blanc''.'),
  ('prod-chateau-petrus', 'Château Pétrus', 'Château Pétrus', 'producer', 'France', 'Bordeaux', 'Pomerol AOC (Right Bank)', ARRAY['Petrus', 'Pétrus', 'Château Pétrus']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC"],"soils":["iron_clay","clay_limestone"],"climates":["maritime"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["bordeaux_family","single_varietal_strict"],"primaryGrapes":["Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 20, '11.4 hectares atop the ''Pétrus Buttonhole''—an island of 40-million-year-old dark blue smectite clay over iron-rich ''crasse de fer'' where 100% Merlot reaches unmatched black truffle and mulberry density.'),
  ('prod-chateau-dyquem', 'Château d''Yquem', 'Château d''Yquem', 'producer', 'France', 'Bordeaux', 'Sauternes AOC', ARRAY['Yquem', 'Chateau d''Yquem', 'Château d''Yquem']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","Classed_Growth_1855","Grand_Cru"],"soils":["gravel_alluvial","clay_limestone"],"climates":["maritime","cooling_fog_current"],"waterBodies":["gironde_estuary","major_river"],"styles":["botrytis_sweet","dry_white"],"vinification":["new_french_oak"],"sensory":["honey_saffron_botrytis","laser_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Sémillon","Sauvignon Blanc"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 21, 'The sole ''Premier Cru Supérieur'' of the 1855 Classification. Pickers make up to 6–10 passes (''tries'') through the vineyard harvesting individual botrytized berries, yielding roughly one glass of wine per vine.'),
  ('prod-krug', 'Krug (Maison de Champagne)', 'Krug', 'producer', 'France', 'Champagne', 'Reims / Le Mesnil-sur-Oger / Ambonnay', ARRAY['Krug', 'Krug Grande Cuvée', 'Clos du Mesnil', 'Clos d''Ambonnay']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["limestone_chalk"],"climates":["continental","maritime"],"waterBodies":["major_river"],"styles":["sparkling_traditional"],"vinification":["sur_lie_autolysis","extended_aging_36m","no_malolactic"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","multi_blend_tradition","single_varietal_strict"],"primaryGrapes":["Chardonnay","Pinot Noir","Pinot Meunier"],"bottleShapes":["champagne_heavy","specialty_traditional"],"heritage":["codified_pre_1855","unesco_landscape"]}'::jsonb, 22, 'Founded in 1843 by Joseph Krug. Every single parcel is primary-fermented in small 205-liter Argonne oak casks without malolactic fermentation before 6+ years of lees aging for Grande Cuvée and single-walled-vineyard Clos du Mesnil.'),
  ('prod-guigal', 'E. Guigal (La Mouline / La Landonne / La Turque)', 'E. Guigal', 'producer', 'France', 'Rhône Valley', 'Ampuis (Côte-Rôtie AOC)', ARRAY['Guigal', 'E. Guigal', 'LaLaLa', 'La Mouline', 'La Landonne', 'La Turque']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["slate_schist","granite"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red","dry_white"],"vinification":["co_fermentation","new_french_oak","extended_aging_36m"],"sensory":["rotundone_black_pepper","violet_rose_floral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["rhone_family","aromatic_white"],"primaryGrapes":["Syrah","Viognier"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 29, 'Famous for the ''La-La-La'' single-vineyard Côte-Rôtie trio (La Mouline on Côte Blonde with up to 11% co-fermented Viognier, La Landonne 100% Syrah on Côte Brune, and La Turque), aged up to 42 months in 100% new oak produced at Guigal''s own cooperage.'),
  ('prod-chateau-rayas', 'Château Rayas (Emmanuel Reynaud)', 'Château Rayas', 'producer', 'France', 'Rhône Valley', 'Châteauneuf-du-Pape AOC', ARRAY['Rayas', 'Chateau Rayas', 'Château Rayas']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC"],"soils":["sand_phylloxera_free"],"climates":["mediterranean"],"waterBodies":["rhone_river","major_river"],"styles":["dry_red","dry_white"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster"],"sensory":["low_tannin_delicate","violet_rose_floral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["rhone_family","single_varietal_strict"],"primaryGrapes":["Grenache","Clairette"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines"]}'::jsonb, 43, 'Unlike the galets roulés pebbles of neighboring Châteauneuf estates, Rayas sits in a cool, pine-ringed clearing of pure fine sand (''sable'') and is crafted from 100% old-vine Grenache aged in ancient demi-muids, achieving Burgundian weightlessness.'),
  ('prod-giacomo-conterno', 'Giacomo Conterno (Monfortino)', 'Giacomo Conterno', 'producer', 'Italy', 'Piedmont', 'Serralunga d''Alba (Barolo DOCG)', ARRAY['Giacomo Conterno', 'Monfortino', 'Barolo Monfortino']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills","cooling_fog_current"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Nebbiolo"],"bottleShapes":["burgundy_slope"],"heritage":["unesco_landscape"]}'::jsonb, 34, 'The arch-traditionalist benchmark of Barolo. Its flagship Barolo Riserva ''Monfortino'' from the Francia and Arione crus in Serralunga d''Alba undergoes submerged-cap maceration for up to 4–5 weeks and ages for 7 years in large Austrian oak botti.'),
  ('prod-gaja', 'Gaja (Barbaresco & Barolo)', 'Gaja', 'producer', 'Italy', 'Piedmont', 'Barbaresco DOCG & Barolo DOCG', ARRAY['Gaja', 'Angelo Gaja', 'Sorì San Lorenzo', 'Sorì Tildìn', 'Sperss']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills","cooling_fog_current"],"waterBodies":["major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","large_neutral_botte_foudre"],"sensory":["high_tannin_high_acid","violet_rose_floral","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","burgundy_family","bordeaux_family","single_varietal_strict"],"primaryGrapes":["Nebbiolo","Chardonnay","Cabernet Sauvignon"],"bottleShapes":["burgundy_slope"],"heritage":["unesco_landscape"]}'::jsonb, 24, 'Founded in 1859 in Barbaresco and revolutionized by Angelo Gaja, who introduced single-vineyard crus (Sorì San Lorenzo, Sorì Tildìn, Costa Russi), green harvesting, and combined barrique + botte maturation to Piedmont.'),
  ('prod-sassicaia', 'Tenuta San Guido (Sassicaia)', 'Tenuta San Guido (Sassicaia)', 'producer', 'Italy', 'Tuscany', 'Bolgheri Sassicaia DOC', ARRAY['Sassicaia', 'Tenuta San Guido']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO","Super_Tuscan"],"soils":["gravel_alluvial","clay_limestone"],"climates":["mediterranean","maritime"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 20, 'Planted in the 1940s by Marchese Mario Incisa della Rocchetta using Cabernet cuttings from Pisa and Château Lafite on stony gravel (''sassicaia''). First commercially released with the 1968 vintage, launching the Super Tuscan movement.'),
  ('prod-vega-sicilia', 'Vega Sicilia (Único)', 'Vega Sicilia', 'producer', 'Spain', 'Castilla y León', 'Ribera del Duero DO', ARRAY['Vega Sicilia', 'Unico', 'Vega Sicilia Único', 'Valbuena 5']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["PDO_DO"],"soils":["clay_limestone","limestone_chalk","gravel_alluvial"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":["ebro_duero","douro_river","major_river"],"styles":["dry_red"],"vinification":["new_french_oak","large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Tempranillo","Cabernet Sauvignon","Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 22, 'Founded in 1864 by Eloy Lecanda with Bordeaux cuttings alongside Tinto Fino (Tempranillo). ''Único'' ages at least 10 years in American and French oak vats, barrels, and bottle before release; ''Único Reserva Especial'' blends multiple great vintages.'),
  ('prod-lopez-de-heredia', 'R. López de Heredia (Viña Tondonia)', 'López de Heredia (Viña Tondonia)', 'producer', 'Spain', 'Ebro Valley', 'Haro (Rioja Alta, Rioja DOCa)', ARRAY['Lopez de Heredia', 'López de Heredia', 'Viña Tondonia', 'Vina Tondonia']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCa"],"soils":["clay_limestone","gravel_alluvial"],"climates":["continental","high_altitude","rain_shadow"],"waterBodies":["ebro_duero","major_river"],"styles":["dry_red","dry_white","rose_specialist","oxidative_biological"],"vinification":["extended_aging_36m","large_neutral_botte_foudre"],"sensory":["laser_high_acid","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["iberian_indigenous","multi_blend_tradition"],"primaryGrapes":["Tempranillo","Garnacha","Graciano","Mazuelo","Viura","Malvasía"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines"]}'::jsonb, 28, 'Founded in 1877 in Haro. Famous for aging its Viña Tondonia Blanco, Rosado, and Tinto Reserva/Gran Reserva for 4 to 10+ years in seasoned American oak barrels coopered on-site, followed by years in bottle.'),
  ('prod-egon-muller', 'Weingut Egon Müller (Scharzhofberger)', 'Egon Müller (Scharzhofberger)', 'producer', 'Germany', 'Mosel', 'Saar (Wiltingen)', ARRAY['Egon Muller', 'Egon Müller', 'Scharzhofberger']::text[], '{"countryCode":"DE","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Pradikatswein_VDP","PDO_DO","Grand_Cru"],"soils":["slate_schist"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["laser_high_acid","low_abv_delicate","petrol_tdn","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["aromatic_white","single_varietal_strict"],"primaryGrapes":["Riesling"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["ungrafted_pre_phylloxera","monastic_origin","codified_pre_1855"]}'::jsonb, 33, 'In the chilly Saar tributary on weathered grey Devonian slate, Egon Müller crafts the world''s most sought-after Rieslings from century-old ungrafted vines on the Scharzhofberg monopole-style hill.'),
  ('prod-penfolds', 'Penfolds (Grange)', 'Penfolds (Grange)', 'producer', 'Australia', 'South Australia', 'Barossa Valley / McLaren Vale / Adelaide Hills', ARRAY['Penfolds', 'Penfolds Grange', 'Grange Hermitage', 'Bin 707']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["sand_phylloxera_free","iron_clay","terra_rossa"],"climates":["mediterranean","continental"],"waterBodies":[],"styles":["dry_red","dry_white","fortified"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","rotundone_black_pepper","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["rhone_family","bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Shiraz","Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","bush_vines","codified_pre_1855"]}'::jsonb, 20, 'Founded in 1844 by Dr. Christopher Rawson Penfold. Chief winemaker Max Schubert created Grange in 1951—a multi-vineyard, multi-district South Australian Shiraz (with a dash of Cabernet Sauvignon) fermented and aged in 100% new American oak hogsheads.'),
  ('prod-catena-zapata', 'Bodega Catena Zapata (Adrianna Vineyard)', 'Catena Zapata', 'producer', 'Argentina', 'Cuyo', 'Gualtallary, Uco Valley (Mendoza)', ARRAY['Catena Zapata', 'Nicolás Catena Zapata', 'Adrianna Vineyard', 'Mundus Bacillus Terrae']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["limestone_chalk","gravel_alluvial"],"climates":["continental","high_altitude","diurnal_shift","alpine_foothills","rain_shadow"],"waterBodies":["major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak","flor_yeast","sur_lie_autolysis"],"sensory":["full_bodied_high_abv","violet_rose_floral","high_tannin_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["bordeaux_family","burgundy_family","single_varietal_strict"],"primaryGrapes":["Malbec","Chardonnay","Cabernet Sauvignon","Cabernet Franc"],"bottleShapes":["bordeaux_shoulder","burgundy_slope"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 26, 'Pioneered extreme high-altitude viticulture in Mendoza under Nicolás and Dr. Laura Catena, planting the Adrianna Vineyard at nearly 1,500m elevation in Gualtallary on calcareous alluvial riverbeds.'),
  ('prod-screaming-eagle', 'Screaming Eagle', 'Screaming Eagle', 'producer', 'United States', 'California', 'Oakville AVA (Napa Valley)', ARRAY['Screaming Eagle']::text[], '{"countryCode":"US","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AVA"],"soils":["volcanic_basalt","gravel_alluvial"],"climates":["mediterranean","cooling_fog_current","diurnal_shift"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","high_tannin_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Sauvignon Blanc"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 24, 'A tiny Oakville AVA Cabernet estate in Napa Valley. The vines sit on volcanic rock and gravel, and the wine ages in new French oak.'),
  ('prod-chateau-musar', 'Château Musar (Gaston Hochar)', 'Château Musar', 'producer', 'Lebanon', 'Bekaa', 'Bekaa Valley', ARRAY['Chateau Musar', 'Château Musar', 'Musar']::text[], '{"countryCode":"LB","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["gravel_alluvial","limestone_chalk","clay_limestone"],"climates":["mediterranean","high_altitude","diurnal_shift"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","dry_white","rose_specialist"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["bordeaux_family","rhone_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Cinsault","Carignan","Obaideh","Merwah"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 39, 'Founded in 1930 by Gaston Hochar and made famous by Serge Hochar, who harvested through the Lebanese Civil War. Blends high-altitude Bekaa Valley Cabernet Sauvignon, Cinsault, and Carignan (and ancient ungrafted Obaideh & Merwah for whites), releasing wines only after 7 years.'),
  ('app-vouvray', 'Vouvray AOC', 'Vouvray', 'appellation', 'France', 'Loire Valley', 'Touraine', ARRAY['Vouvray', 'Vouvray Moelleux', 'Vouvray Pétillant']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["tuffeau","limestone_chalk","clay_limestone"],"climates":["maritime","continental","cooling_fog_current"],"waterBodies":["loire_river","major_river"],"styles":["dry_white","sparkling_traditional","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic","sur_lie_autolysis"],"sensory":["laser_high_acid","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Chenin Blanc"],"bottleShapes":["burgundy_slope","champagne_heavy"],"heritage":["unesco_landscape","monastic_origin"]}'::jsonb, 29, '100% Chenin Blanc (Pineau de la Loire) grown on Turonian ''tuffeau'' chalk plateaus excavated into deep subterranean aging cellars. Produces Sec, Demi-Sec, botrytized Moelleux/Liquoreux, and Traditional Method sparkling.'),
  ('app-condrieu', 'Condrieu AOC', 'Condrieu', 'appellation', 'France', 'Rhône Valley', 'Northern Rhône', ARRAY['Condrieu']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC"],"soils":["granite"],"climates":["continental","steep_heroic_slopes"],"waterBodies":["rhone_river","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["new_french_oak","sur_lie_autolysis"],"sensory":["full_bodied_high_abv","violet_rose_floral"],"varietalTraits":["rhone_family","aromatic_white","single_varietal_strict"],"primaryGrapes":["Viognier"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 34, '100% Viognier grown on steep decomposed biotite granite (''arzelle'') terraces overlooking the Rhône River, famed for heady apricot, white peach, and violet blossom perfume.'),
  ('app-banyuls', 'Banyuls / Banyuls Grand Cru AOC', 'Banyuls', 'appellation', 'France', 'Roussillon', 'Côte Vermeille (Pyrenees)', ARRAY['Banyuls', 'Banyuls Grand Cru']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AOC","Grand_Cru"],"soils":["slate_schist"],"climates":["mediterranean","steep_heroic_slopes"],"waterBodies":["mediterranean_sea"],"styles":["fortified","oxidative_biological"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["rhone_family","iberian_indigenous","multi_blend_tradition"],"primaryGrapes":["Grenache Noir","Grenache Gris","Carignan"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines"]}'::jsonb, 52, 'France''s flagship red Vin Doux Naturel (VDN) on vertical Cambrian schist terraces plunging into the Mediterranean. Arrested by mutage with neutral grape spirit and often aged oxidatively in glass demijohns (''bonbonnes'') outdoors in the sun.'),
  ('app-cava', 'Cava DO', 'Cava', 'appellation', 'Spain', 'Catalonia', 'Penedès (Sant Sadurní d''Anoia)', ARRAY['Cava', 'Cava de Paraje Calificado']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["clay_limestone","limestone_chalk"],"climates":["mediterranean"],"waterBodies":["mediterranean_sea"],"styles":["sparkling_traditional","rose_specialist"],"vinification":["sur_lie_autolysis","extended_aging_36m"],"sensory":["laser_high_acid","saline_mineral"],"varietalTraits":["iberian_indigenous","burgundy_family","multi_blend_tradition"],"primaryGrapes":["Xarel·lo","Macabeo","Parellada","Chardonnay","Pinot Noir"],"bottleShapes":["champagne_heavy"],"heritage":[]}'::jsonb, 21, 'Traditional Method Spanish sparkling wine centered in Penedès since 1872, driven by indigenous trio Xarel·lo (providing resveratrol-rich structure and earthy grip), Macabeo, and high-altitude Parellada.'),
  ('app-vinho-verde', 'Vinho Verde DOC', 'Vinho Verde', 'appellation', 'Portugal', 'Minho', 'Monção e Melgaço / Lima', ARRAY['Vinho Verde']::text[], '{"countryCode":"PT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["PDO_DO"],"soils":["granite"],"climates":["maritime"],"waterBodies":["atlantic_ocean","major_river"],"styles":["dry_white","rose_specialist","dry_red"],"vinification":["amphora_concrete_unoaked","no_malolactic","sur_lie_autolysis"],"sensory":["laser_high_acid","low_abv_delicate","saline_mineral"],"varietalTraits":["iberian_indigenous","aromatic_white","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Alvarinho","Loureiro","Arinto","Trajadura"],"bottleShapes":["alsace_flute_schlegel","burgundy_slope"],"heritage":[]}'::jsonb, 26, 'Portugal''s largest DOC in the lush, rainy northwest between the Minho and Douro rivers. Decomposed granite soils yield zesty, low-alcohol whites from Alvarinho and floral Loureiro.'),
  ('app-ahr', 'Ahr (Prädikatswein / VDP)', 'Ahr', 'appellation', 'Germany', 'Ahr Valley', 'Walporzheim / Mayschoss / Dernau', ARRAY['Ahr', 'Ahr Spätburgunder']::text[], '{"countryCode":"DE","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["Pradikatswein_VDP","PDO_DO","Grand_Cru"],"soils":["slate_schist","volcanic_basalt","loess_silt"],"climates":["continental","steep_heroic_slopes","rain_shadow"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["low_tannin_delicate","laser_high_acid","violet_rose_floral","saline_mineral"],"varietalTraits":["burgundy_family","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Spätburgunder (Pinot Noir)","Frühburgunder"],"bottleShapes":["burgundy_slope"],"heritage":["monastic_origin"]}'::jsonb, 50, 'Despite sitting above 50.5°N latitude, over 80% of the Ahr''s steep Devonian slate and greywacke gorge is planted to red grapes (Spätburgunder and early-ripening mutation Frühburgunder), warmed by the Eifel Mountains rain shadow.'),
  ('app-burgenland', 'Burgenland / Leithaberg & Mittelburgenland DAC', 'Burgenland', 'appellation', 'Austria', 'Burgenland', 'Neusiedlersee / Leithaberg / Mittelburgenland / Eisenberg', ARRAY['Burgenland', 'Leithaberg DAC', 'Mittelburgenland DAC', 'Neusiedlersee DAC']::text[], '{"countryCode":"AT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DAC","PDO_DO"],"soils":["limestone_chalk","slate_schist","iron_clay"],"climates":["continental","cooling_fog_current"],"waterBodies":[],"styles":["dry_red","botrytis_sweet","dry_white"],"vinification":["large_neutral_botte_foudre","new_french_oak"],"sensory":["high_tannin_high_acid","rotundone_black_pepper","honey_saffron_botrytis","long_cellar_20yr"],"varietalTraits":["single_varietal_strict"],"primaryGrapes":["Blaufränkisch","Zweigelt","St. Laurent","Welschriesling","Chardonnay"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["unesco_landscape","biodynamic_pioneer"]}'::jsonb, 42, 'Bordering Hungary around the shallow evaporative Lake Neusiedl, producing both world-class botrytized Trockenbeerenauslese (''Ruster Ausbruch'') and spicy, mineral-driven Blaufränkisch on Leithakalk shell-limestone and mica-schist.'),
  ('app-salta-cafayate', 'Salta / Calchaquí Valley (Cafayate) GI', 'Salta / Cafayate', 'appellation', 'Argentina', 'North Argentina', 'Cafayate / Molinos', ARRAY['Salta', 'Cafayate', 'Calchaquí Valley', 'Valles Calchaquíes']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["sand_phylloxera_free","granite","gravel_alluvial"],"climates":["continental","high_altitude","diurnal_shift","rain_shadow","alpine_foothills"],"waterBodies":["major_river"],"styles":["dry_white","dry_red"],"vinification":["amphora_concrete_unoaked","new_french_oak"],"sensory":["full_bodied_high_abv","violet_rose_floral","high_tannin_high_acid"],"varietalTraits":["aromatic_white","bordeaux_family","single_varietal_strict"],"primaryGrapes":["Torrontés","Malbec","Tannat","Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 38, 'Home to some of the highest commercial vineyards on Earth (1,700m to over 3,100m above sea level). Intense solar radiation and 20°C+ diurnal swings produce terpene-rich Torrontés Riojano and inky, thick-skinned Malbec and Tannat.'),
  ('app-swartland-constantia', 'Swartland & Constantia WO', 'Swartland', 'appellation', 'South Africa', 'Coastal Region', 'Paardeberg / Riebeekberg / Constantia', ARRAY['Swartland', 'Constantia', 'Vin de Constance']::text[], '{"countryCode":"ZA","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["GI"],"soils":["granite","slate_schist"],"climates":["mediterranean","cooling_fog_current"],"waterBodies":["atlantic_ocean"],"styles":["dry_white","dry_red","passito_appassimento"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster","amphora_concrete_unoaked"],"sensory":["saline_mineral","laser_high_acid","long_cellar_20yr"],"varietalTraits":["rhone_family","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Chenin Blanc","Syrah","Grenache","Cinsault","Muscat de Frontignan"],"bottleShapes":["burgundy_slope","specialty_traditional"],"heritage":["bush_vines","codified_pre_1855","biodynamic_pioneer"]}'::jsonb, 36, 'Swartland''s dry-farmed old bush-vine Chenin Blanc and Syrah on Paardeberg granite and Malmesbury schist lead South Africa''s new wave, while nearby Constantia (founded 1685) crafted Napoleon''s beloved sweet ''Vin de Constance''.'),
  ('grape-mourvedre', 'Mourvèdre / Monastrell / Mataro (Grape)', 'Mourvèdre', 'grape', 'Spain', 'Murcia (Jumilla)', 'Bandol AOC / Jumilla DO / Châteauneuf-du-Pape / Barossa', ARRAY['Mourvedre', 'Mourvèdre', 'Monastrell', 'Mataro']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":["France"],"alsoRegions":["Provence","Rhône Valley"],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AOC","PDO_DO","Autochthonous_Grape"],"soils":["limestone_chalk","clay_limestone","sand_phylloxera_free"],"climates":["mediterranean","steep_heroic_slopes"],"waterBodies":["mediterranean_sea","rhone_river"],"styles":["dry_red","rose_specialist"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["rhone_family","iberian_indigenous","thick_skin_late_ripening","multi_blend_tradition"],"primaryGrapes":["Mourvèdre"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 28, 'Needs ''its head in the hot sun and its feet in water''—the last grape to bud and the last to ripen in the Mediterranean, providing wild game, black plum, garrigue thyme, and muscular tannic backbone to Bandol and GSM blends.'),
  ('grape-barbera', 'Barbera (Grape)', 'Barbera', 'grape', 'Italy', 'Piedmont', 'Barbera d''Asti DOCG & Barbera d''Alba DOC', ARRAY['Barbera', 'Barbera d''Asti', 'Barbera d''Alba']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG","PDO_DO","Autochthonous_Grape"],"soils":["clay_limestone","limestone_chalk"],"climates":["continental","alpine_foothills"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak","large_neutral_botte_foudre","amphora_concrete_unoaked"],"sensory":["laser_high_acid","low_tannin_delicate","full_bodied_high_abv"],"varietalTraits":["italian_indigenous","single_varietal_strict"],"primaryGrapes":["Barbera"],"bottleShapes":["burgundy_slope"],"heritage":["unesco_landscape"]}'::jsonb, 26, 'The structural polar opposite of its Piedmontese neighbor Nebbiolo: Barbera boasts deep ruby-purple color, electric natural acidity, and virtually no astringent tannins.'),
  ('grape-corvina', 'Corvina Veronese (Grape)', 'Corvina', 'grape', 'Italy', 'Veneto', 'Valpolicella / Amarone / Bardolino', ARRAY['Corvina', 'Corvina Veronese']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DOCG","PDO_DO","Autochthonous_Grape"],"soils":["limestone_chalk","volcanic_basalt","clay_limestone"],"climates":["continental","alpine_foothills"],"waterBodies":[],"styles":["passito_appassimento","dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["laser_high_acid","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["italian_indigenous","thick_skin_late_ripening","multi_blend_tradition"],"primaryGrapes":["Corvina"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":[]}'::jsonb, 33, 'The indispensable heart (45–95%) of Valpolicella and Amarone. Its thick cuticles protect berries from rot during 4 months of winter ''appassimento'' drying while generating glycerol and sour-cherry/bitter-almond complexity.'),
  ('grape-aglianico', 'Aglianico (Grape)', 'Aglianico', 'grape', 'Italy', 'Campania & Basilicata', 'Taurasi DOCG / Aglianico del Vulture DOCG', ARRAY['Aglianico', 'Aglianico del Vulture']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG","Autochthonous_Grape"],"soils":["volcanic_basalt","clay_limestone"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","thick_skin_late_ripening","single_varietal_strict"],"primaryGrapes":["Aglianico"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera","codified_pre_1855"]}'::jsonb, 38, 'Thrives especially on high-altitude volcanic soils (Mount Vulture in Basilicata and Irpinia near Vesuvius), combining volcanic smoke, black cherry, iron, and massive tannic-acidic structure.'),
  ('grape-carmenere', 'Carménère (Grape)', 'Carménère', 'grape', 'Chile', 'Central Valley', 'Colchagua (Apalta) / Cachapoal (Peumo) / Maipo', ARRAY['Carmenere', 'Carménère', 'Grande Vidure']::text[], '{"countryCode":"CL","originCountries":["France"],"alsoCountries":[],"alsoRegions":["Bordeaux"],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["PDO_DO","Noble_Grape"],"soils":["gravel_alluvial","granite","clay_limestone"],"climates":["mediterranean","diurnal_shift"],"waterBodies":["pacific_ocean","major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","rotundone_black_pepper"],"varietalTraits":["bordeaux_family","thick_skin_late_ripening","single_varietal_strict","multi_blend_tradition"],"primaryGrapes":["Carménère"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 24, 'An original 18th-century Bordeaux Médoc grape (Cabernet Franc × Gros Cabernet) nearly wiped out in Europe by phylloxera and coulure, rediscovered in Chile in 1994 by French ampelographer Jean-Michel Boursiquot after being mistaken for Merlot for a century.'),
  ('grape-zinfandel', 'Zinfandel / Primitivo / Tribidrag (Grape)', 'Zinfandel', 'grape', 'United States', 'California', 'Sonoma (Dry Creek / Russian River) / Napa / Puglia (Manduria)', ARRAY['Zinfandel', 'Primitivo', 'Tribidrag', 'Crljenak Kaštelanski']::text[], '{"countryCode":"US","originCountries":["Croatia"],"alsoCountries":["Italy"],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AVA","DOCG"],"soils":["gravel_alluvial","terra_rossa","sand_phylloxera_free"],"climates":["mediterranean","diurnal_shift"],"waterBodies":["pacific_ocean","mediterranean_sea"],"styles":["dry_red","passito_appassimento","rose_specialist"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","rotundone_black_pepper"],"varietalTraits":["thin_skin_early_ripening","single_varietal_strict"],"primaryGrapes":["Zinfandel"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 20, 'Genetically identical to Italian Primitivo and ancient Croatian Tribidrag (Crljenak Kaštelanski). Uneven ripening within each cluster means raisined berries and tart red berries co-exist at harvest, creating brambly blackberry jam, black pepper, and high alcohol.'),
  ('grape-pinotage', 'Pinotage (Grape)', 'Pinotage', 'grape', 'South Africa', 'Coastal Region', 'Stellenbosch / Swartland', ARRAY['Pinotage']::text[], '{"countryCode":"ZA","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":true,"classifications":["GI"],"soils":["granite","slate_schist"],"climates":["mediterranean","cooling_fog_current"],"waterBodies":["atlantic_ocean"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv","earthy_truffle_tar"],"varietalTraits":["burgundy_family","rhone_family","thick_skin_late_ripening","single_varietal_strict"],"primaryGrapes":["Pinotage"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["bush_vines"]}'::jsonb, 30, 'Bred in 1925 at Stellenbosch University by Professor Abraham Izak Perold by crossing Pinot Noir × Cinsault (then called ''Hermitage'' in South Africa).'),
  ('grape-gewurztraminer', 'Gewürztraminer (Grape)', 'Gewürztraminer', 'grape', 'France', 'Alsace', 'Alsace Grand Cru & Alto Adige (Tramin)', ARRAY['Gewurztraminer', 'Gewürztraminer', 'Traminer Aromatico']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru","PDO_DO"],"soils":["clay_limestone","limestone_chalk","granite"],"climates":["continental","rain_shadow","alpine_foothills"],"waterBodies":["mosel_rhine","major_river"],"styles":["dry_white","botrytis_sweet"],"vinification":["large_neutral_botte_foudre","no_malolactic"],"sensory":["full_bodied_high_abv","violet_rose_floral","honey_saffron_botrytis"],"varietalTraits":["aromatic_white","single_varietal_strict","thick_skin_late_ripening"],"primaryGrapes":["Gewürztraminer"],"bottleShapes":["alsace_flute_schlegel"],"heritage":["biodynamic_pioneer"]}'::jsonb, 22, 'A pink-skinned aromatic mutation of Savagnin Rose whose signature aroma compound is cis-rose oxide, exploding with lychee, Turkish delight, rosewater, and ginger.'),
  ('grape-semillon', 'Sémillon (Grape)', 'Sémillon', 'grape', 'France', 'Bordeaux', 'Sauternes / Barsac / Pessac-Léognan / Hunter Valley', ARRAY['Semillon', 'Sémillon']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":["Australia"],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["AOC","First_Growth_1855","GI","Noble_Grape"],"soils":["gravel_alluvial","clay_limestone","sand_phylloxera_free"],"climates":["maritime","cooling_fog_current"],"waterBodies":["gironde_estuary","pacific_ocean","major_river"],"styles":["botrytis_sweet","dry_white"],"vinification":["new_french_oak","amphora_concrete_unoaked"],"sensory":["honey_saffron_botrytis","laser_high_acid","low_abv_delicate","long_cellar_20yr"],"varietalTraits":["bordeaux_family","thin_skin_early_ripening","multi_blend_tradition","single_varietal_strict"],"primaryGrapes":["Sémillon"],"bottleShapes":["bordeaux_shoulder","alsace_flute_schlegel"],"heritage":["codified_pre_1855"]}'::jsonb, 25, 'Plays two legendary roles: in Sauternes, its thin golden skin welcomes noble rot for opulent apricot-and-saffron nectar; in Australia''s Hunter Valley, it is harvested early at ~10.5% ABV and aged unaided in bottle into toast, lanolin, and lemon curd complexity.'),
  ('prod-selosse', 'Jacques Selosse (Anselme Selosse)', 'Jacques Selosse', 'producer', 'France', 'Champagne', 'Avize (Côte des Blancs Grand Cru)', ARRAY['Jacques Selosse', 'Selosse', 'Substance']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["limestone_chalk"],"climates":["continental","maritime"],"waterBodies":[],"styles":["sparkling_traditional","oxidative_biological"],"vinification":["solera_system","sur_lie_autolysis","new_french_oak","no_malolactic"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","single_varietal_strict"],"primaryGrapes":["Chardonnay","Pinot Noir"],"bottleShapes":["champagne_heavy"],"heritage":["biodynamic_pioneer","unesco_landscape"]}'::jsonb, 39, 'The godfather of the Grower Champagne movement in Avize. Famous for ''Substance''—a Grand Cru Blanc de Blancs Champagne crafted using a Jerez-inspired Solera system started in 1986.'),
  ('prod-raveneau', 'Domaine François Raveneau', 'Domaine Raveneau', 'producer', 'France', 'Burgundy', 'Chablis AOC (Les Clos / Valmur / Montée de Tonnerre)', ARRAY['Raveneau', 'Domaine Raveneau', 'Francois Raveneau']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["AOC","Grand_Cru"],"soils":["kimmeridgian_marl","limestone_chalk"],"climates":["continental"],"waterBodies":["major_river"],"styles":["dry_white"],"vinification":["large_neutral_botte_foudre","sur_lie_autolysis"],"sensory":["laser_high_acid","saline_mineral","long_cellar_20yr"],"varietalTraits":["burgundy_family","single_varietal_strict"],"primaryGrapes":["Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 41, 'Founded in 1948 in Chablis, owning parcels in three Grand Crus (Les Clos, Valmur, Blanchot) and six Premier Crus on steep Kimmeridgian oyster-marl slopes, aged in seasoned Feuillettes (132L barrels) and sealed with wax.'),
  ('prod-tempier', 'Domaine Tempier (Lulu & Lucien Peyraud)', 'Domaine Tempier', 'producer', 'France', 'Provence', 'Bandol AOC (La Migoua / La Tourtine / Cabassaou)', ARRAY['Domaine Tempier', 'Tempier', 'Bandol Tempier']::text[], '{"countryCode":"FR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AOC"],"soils":["limestone_chalk","clay_limestone"],"climates":["mediterranean","steep_heroic_slopes"],"waterBodies":["mediterranean_sea"],"styles":["dry_red","rose_specialist"],"vinification":["large_neutral_botte_foudre","carbonic_whole_cluster"],"sensory":["high_tannin_high_acid","full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["rhone_family","multi_blend_tradition","thick_skin_late_ripening"],"primaryGrapes":["Mourvèdre","Grenache","Cinsault"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","biodynamic_pioneer"]}'::jsonb, 38, 'Saved Mourvèdre from post-war replacement in Bandol under Lucien and Lulu Peyraud. Their single-vineyard red crus (up to 95% Mourvèdre in Cabassaou) and gastronomical Bandol Rosé are icons of French viticulture.'),
  ('prod-biondi-santi', 'Biondi-Santi (Tenuta Greppo)', 'Biondi-Santi', 'producer', 'Italy', 'Tuscany', 'Brunello di Montalcino DOCG', ARRAY['Biondi-Santi', 'Tenuta Greppo', 'Il Greppo']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCG"],"soils":["clay_limestone","slate_schist"],"climates":["mediterranean","high_altitude","rain_shadow"],"waterBodies":[],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["high_tannin_high_acid","laser_high_acid","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","single_varietal_strict","thin_skin_early_ripening"],"primaryGrapes":["Sangiovese"],"bottleShapes":["bordeaux_shoulder"],"heritage":["unesco_landscape"]}'::jsonb, 33, 'The inventor of Brunello di Montalcino: Ferruccio Biondi-Santi bottled the first modern Brunello in 1888 at Tenuta Greppo. The BBS11 clone was selected later by Franco Biondi-Santi with the University of Florence and registered in 1978. The wines age in large Slavonian oak botti for decades.'),
  ('prod-quintarelli', 'Giuseppe Quintarelli', 'Giuseppe Quintarelli', 'producer', 'Italy', 'Veneto', 'Negrar (Valpolicella / Amarone DOCG)', ARRAY['Quintarelli', 'Giuseppe Quintarelli', 'Alzero']::text[], '{"countryCode":"IT","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"cool_north","coastalOrIsland":false,"classifications":["DOCG"],"soils":["limestone_chalk","volcanic_basalt"],"climates":["continental"],"waterBodies":[],"styles":["passito_appassimento","dry_red"],"vinification":["large_neutral_botte_foudre","extended_aging_36m"],"sensory":["full_bodied_high_abv","earthy_truffle_tar","long_cellar_20yr"],"varietalTraits":["italian_indigenous","bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Corvina","Corvinone","Rondinella","Cabernet Franc"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":[]}'::jsonb, 37, '''Il Maestro del Veneto.'' Famous for handwritten labels and aging Amarone della Valpolicella for 7 to 10 years in Slavonian oak botti before release.'),
  ('prod-alvaro-palacios', 'Álvaro Palacios (L''Ermita)', 'Álvaro Palacios (L''Ermita)', 'producer', 'Spain', 'Catalonia', 'Gratallops (Priorat DOCa) & Bierzo DO', ARRAY['Alvaro Palacios', 'Álvaro Palacios', 'L''Ermita', 'Finca Dofí']::text[], '{"countryCode":"ES","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"Old World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["DOCa","Grand_Cru"],"soils":["slate_schist"],"climates":["mediterranean","steep_heroic_slopes","high_altitude"],"waterBodies":["mediterranean_sea"],"styles":["dry_red"],"vinification":["large_neutral_botte_foudre","new_french_oak"],"sensory":["full_bodied_high_abv","saline_mineral","violet_rose_floral","long_cellar_20yr"],"varietalTraits":["rhone_family","iberian_indigenous","single_varietal_strict"],"primaryGrapes":["Garnacha","Cariñena","Mencía"],"bottleShapes":["burgundy_slope","bordeaux_shoulder"],"heritage":["bush_vines","biodynamic_pioneer"]}'::jsonb, 35, 'Leader of the 1989 Priorat renaissance. ''L''Ermita'' is a dizzyingly steep North-East facing amphitheater of llicorella quartz-slate planted between 1910 and 1939 to old-vine Garnacha, holding Priorat''s ''Gran Vinya Classificada'' Grand Cru status.'),
  ('prod-henschke', 'Henschke (Hill of Grace)', 'Henschke (Hill of Grace)', 'producer', 'Australia', 'South Australia', 'Eden Valley GI', ARRAY['Henschke', 'Hill of Grace', 'Mount Edelstone']::text[], '{"countryCode":"AU","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["sand_phylloxera_free","clay_limestone"],"climates":["continental","high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["new_french_oak"],"sensory":["rotundone_black_pepper","violet_rose_floral","full_bodied_high_abv","long_cellar_20yr"],"varietalTraits":["rhone_family","aromatic_white","single_varietal_strict"],"primaryGrapes":["Shiraz","Riesling"],"bottleShapes":["burgundy_slope","alsace_flute_schlegel"],"heritage":["ungrafted_pre_phylloxera","biodynamic_pioneer"]}'::jsonb, 31, 'Australia''s greatest single-vineyard wine: ''Hill of Grace'' is crafted from the ''Grandfathers'' block of pre-phylloxera ungrafted Shiraz vines planted around 1860 in high-altitude Eden Valley opposite the Gnadenberg Lutheran Church.'),
  ('prod-ridge', 'Ridge Vineyards (Monte Bello)', 'Ridge Vineyards (Monte Bello)', 'producer', 'United States', 'California', 'Santa Cruz Mountains AVA & Sonoma', ARRAY['Ridge', 'Ridge Monte Bello', 'Ridge Vineyards', 'Geyserville']::text[], '{"countryCode":"US","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Northern","latitudeBand":"temperate_mid","coastalOrIsland":true,"classifications":["AVA"],"soils":["limestone_chalk","clay_limestone","gravel_alluvial"],"climates":["maritime","high_altitude","cooling_fog_current"],"waterBodies":["pacific_ocean"],"styles":["dry_red","dry_white"],"vinification":["new_french_oak"],"sensory":["high_tannin_high_acid","laser_high_acid","long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Cabernet Franc","Zinfandel","Chardonnay"],"bottleShapes":["bordeaux_shoulder"],"heritage":["bush_vines"]}'::jsonb, 27, 'Guided for decades by winemaker-philosopher Paul Draper. Perched at 400–800m in the cool Santa Cruz Mountains on rare Californian decomposing Franciscan limestone, the 1971 Ridge Monte Bello placed 5th at the 1976 Judgment of Paris and 1st at the 30-year 2006 re-enactment.'),
  ('app-vale-dos-vinhedos', 'Vale dos Vinhedos DO', 'Vale dos Vinhedos', 'appellation', 'Brazil', 'Serra Gaúcha', 'Bento Gonçalves / Garibaldi / Monte Belo do Sul', ARRAY['Vale dos Vinhedos', 'DO Vale dos Vinhedos', 'Vale dos Vinhedos DO', 'Aprovale']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red","dry_white","sparkling_traditional"],"vinification":["sur_lie_autolysis"],"sensory":["low_tannin_delicate"],"varietalTraits":["bordeaux_family","burgundy_family","multi_blend_tradition"],"primaryGrapes":["Merlot","Chardonnay","Pinot Noir","Cabernet Sauvignon","Cabernet Franc","Tannat","Riesling Itálico"],"bottleShapes":["bordeaux_shoulder","champagne_heavy"],"heritage":[]}'::jsonb, 60, 'Brazil''s first geographical indication (IP, 2002) and first Denominação de Origem (2012): 72.45 km² of Serra Geral volcanic plateau in Bento Gonçalves, Garibaldi and Monte Belo do Sul. DO reds must be built on Merlot (at least 60% of a blend), and DO sparkling wines are traditional method only, with at least 9 months on the lees.'),
  ('app-altos-de-pinto-bandeira', 'Altos de Pinto Bandeira DO', 'Altos de Pinto Bandeira', 'appellation', 'Brazil', 'Serra Gaúcha', 'Pinto Bandeira / Farroupilha / Bento Gonçalves (520–770 m)', ARRAY['Altos de Pinto Bandeira', 'Pinto Bandeira', 'IP Pinto Bandeira', 'Asprovinho']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["sparkling_traditional"],"vinification":["sur_lie_autolysis"],"sensory":["low_tannin_delicate"],"varietalTraits":["burgundy_family","multi_blend_tradition"],"primaryGrapes":["Chardonnay","Pinot Noir","Riesling Itálico"],"bottleShapes":["champagne_heavy"],"heritage":[]}'::jsonb, 72, 'A Denominação de Origem for sparkling wine only (INPI, 2022): 65 km² at 520–770 m on the volcanic Serra Geral plateau. Traditional method exclusively, whole-bunch pressing, at least 12 months on the lees before disgorgement, from Chardonnay, Pinot Noir and no more than 25% Riesling Itálico.'),
  ('app-vinhos-de-altitude-sc', 'Vinhos de Altitude de Santa Catarina IP', 'Vinhos de Altitude de Santa Catarina', 'appellation', 'Brazil', 'Santa Catarina Highlands', 'São Joaquim / Água Doce / Bom Retiro / Urupema (≥ 840 m)', ARRAY['Vinhos de Altitude de Santa Catarina', 'Planalto Catarinense', 'São Joaquim', 'Santa Catarina altitude wines']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt"],"climates":["high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["sur_lie_autolysis"],"sensory":["laser_high_acid"],"varietalTraits":["bordeaux_family","burgundy_family"],"primaryGrapes":["Cabernet Sauvignon","Merlot","Sauvignon Blanc","Pinot Noir","Chardonnay"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 74, 'Brazil''s altitude-wine GI (IP, 2021): only vineyards at 840 m or higher qualify, and most sit between 900 m and 1,400 m on the basalt plateau around São Joaquim, Água Doce, Bom Retiro and Urupema. A mild, dry summer with wide day-night swings keeps malic acid high and gives tart, intense reds; sparkling wines are made by both tank and traditional methods.'),
  ('app-limari', 'Limarí Valley DO', 'Limarí Valley', 'appellation', 'Chile', 'Coquimbo', 'Ovalle / Monte Patria / Punitaqui / Río Hurtado', ARRAY['Limari', 'Limarí', 'Valle del Limarí']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["limestone_chalk"],"climates":["maritime","cooling_fog_current"],"waterBodies":["pacific_ocean"],"styles":["dry_white","sparkling_traditional"],"vinification":["sur_lie_autolysis"],"sensory":["saline_mineral"],"varietalTraits":["burgundy_family"],"primaryGrapes":["Chardonnay","Syrah","Pinot Noir","Sauvignon Blanc"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 55, 'Semi-arid northern valley known for pisco and petroglyphs, cooled by the morning ''camanchaca'' fog. One of the few places in Chile with calcareous soils, it has about 780 ha of Chardonnay — fresh and mineral — plus traditional-method sparkling wine.'),
  ('app-itata', 'Itata Valley DO', 'Itata Valley', 'appellation', 'Chile', 'Southern Chile', 'Guarilihue / Coelemu / Quillón (Ñuble secano)', ARRAY['Itata', 'Valle del Itata', 'Guarilihue', 'Secano Interior']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["granite"],"climates":["mediterranean","maritime"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["amphora_concrete_unoaked"],"sensory":["low_tannin_delicate"],"varietalTraits":["iberian_indigenous","rhone_family"],"primaryGrapes":["País","Moscatel de Alejandría","Cinsault"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 58, 'One of the oldest vineyard areas in the Americas, planted since the 16th century. Dry-farmed, head-trained (''en cabeza'') and largely own-rooted País and Moscatel de Alejandría — joined by Cinsault after the 1939 earthquake — grow on granitic, quartz-rich hillsides, and clay tinajas are the traditional fermentation and ageing vessels. Cinsault here makes light, refreshing reds.'),
  ('grape-torrontes', 'Torrontés Riojano (Grape)', 'Torrontés', 'grape', 'Argentina', 'North Argentina', 'Northwest Argentina', ARRAY['Torrontes', 'Torrontés', 'Torrontés Riojano']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["Autochthonous_Grape"],"soils":["gravel_alluvial"],"climates":["high_altitude","diurnal_shift"],"waterBodies":[],"styles":["dry_white"],"vinification":["amphora_concrete_unoaked"],"sensory":["violet_rose_floral"],"varietalTraits":["aromatic_white","single_varietal_strict"],"primaryGrapes":["Torrontés Riojano"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 34, 'Argentina''s emblematic white. DNA shows Torrontés Riojano is a natural cross of Muscat of Alexandria and Criolla Chica (Listán Prieto, Chile''s País), which explains its dry, Muscat-scented wines. Its home is the high Calchaquí Valleys of Salta, on sandy, gravelly soils with wide day-night swings, where it is usually fermented in stainless steel without oak.'),
  ('grape-pais', 'País / Listán Prieto (Grape)', 'País', 'grape', 'Chile', 'Southern Chile', 'Itata / Maule / Bío-Bío secano', ARRAY['Pais', 'País', 'Listán Prieto', 'Mission', 'Criolla Chica', 'Negra Criolla']::text[], '{"countryCode":"CL","originCountries":["Spain"],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":[],"soils":["granite"],"climates":["mediterranean"],"waterBodies":[],"styles":["dry_red"],"vinification":["carbonic_whole_cluster"],"sensory":["low_tannin_delicate"],"varietalTraits":["iberian_indigenous"],"primaryGrapes":["País"],"bottleShapes":["burgundy_slope"],"heritage":["bush_vines","ungrafted_pre_phylloxera"]}'::jsonb, 55, 'The Spanish Listán Prieto, thought to be the first vinifera brought to the Americas by missionaries — Mission in California, Criolla Chica in Argentina. Itata alone has 3,877 ha of old head-trained, own-rooted vines on granitic soils. The wines are always pale, with rustic tannins that winemakers tame with techniques such as carbonic maceration.'),
  ('prod-cave-geisse', 'Cave Geisse', 'Cave Geisse', 'producer', 'Brazil', 'Serra Gaúcha', 'Pinto Bandeira (Altos de Pinto Bandeira)', ARRAY['Cave Geisse', 'Família Geisse', 'Vinícola Geisse', 'Geisse']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["sparkling_traditional"],"vinification":["sur_lie_autolysis"],"sensory":["low_tannin_delicate"],"varietalTraits":["burgundy_family"],"primaryGrapes":["Chardonnay","Pinot Noir"],"bottleShapes":["champagne_heavy"],"heritage":[]}'::jsonb, 68, 'Founded in Pinto Bandeira in 1979 by the Chilean agronomist and winemaker Mario Geisse, who had come to Brazil in 1976 to run Moët & Chandon''s local operation. Trials of traditional-method sparkling wine began in 1981; today the Cave Geisse Brut is 70% Chardonnay and 30% Pinot Noir with 24 months on the lees, and the 1998 Brut, aged 12 years, showed how well Pinto Bandeira sparkling wine can age.'),
  ('prod-miolo', 'Miolo (Vale dos Vinhedos)', 'Miolo', 'producer', 'Brazil', 'Serra Gaúcha', 'Vale dos Vinhedos DO (Bento Gonçalves)', ARRAY['Miolo', 'Miolo Wine Group', 'Vinícola Miolo', 'Miolo Millésime']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red","sparkling_traditional"],"vinification":["sur_lie_autolysis"],"sensory":["low_tannin_delicate"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Merlot","Chardonnay","Pinot Noir"],"bottleShapes":["bordeaux_shoulder","champagne_heavy"],"heritage":[]}'::jsonb, 60, 'Giuseppe Miolo arrived in Bento Gonçalves in 1897 and bought Lote 43 in what is now the Vale dos Vinhedos; the family winery dates from 1989, and its first bottled wine was a Merlot. The group is Brazil''s largest wine exporter, its Vale dos Vinhedos wines carry the DO seal, and the Millésime sparkling spends at least 18 months on its lees.'),
  ('prod-casa-valduga', 'Casa Valduga', 'Casa Valduga', 'producer', 'Brazil', 'Serra Gaúcha', 'Vale dos Vinhedos (Bento Gonçalves)', ARRAY['Casa Valduga', 'Valduga', 'Famiglia Valduga', 'Storia Merlot']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak","extended_aging_36m"],"sensory":["full_bodied_high_abv"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Merlot","Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 66, 'The Valduga family came from Rovereto in northern Italy at the end of the 19th century and planted some of the first vines in the heart of today''s Vale dos Vinhedos. Its icons mature in French oak and then in underground cellars: Storia Merlot 2020 spent 18 months in new French oak and 50 months in the cellar, at 15.5% alcohol.'),
  ('prod-pizzato', 'Pizzato', 'Pizzato', 'producer', 'Brazil', 'Serra Gaúcha', 'Vale dos Vinhedos (Bento Gonçalves)', ARRAY['Pizzato', 'Vinícola Pizzato', 'Pizzato DNA99', 'DNA99']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["full_bodied_high_abv"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 74, 'A Vale dos Vinhedos family estate: Antônio Pizzato arrived from Italy in 1875, but the family sold its grapes until its first own vintage in 1999 — 15,500 bottles of Merlot. Its DNA99 Merlot is made only in top years, nine times in 25 years, and matures in first-use French oak; the winery calls it full-bodied yet elegant.'),
  ('prod-lidio-carraro', 'Lidio Carraro', 'Lidio Carraro', 'producer', 'Brazil', 'Serra Gaúcha', 'Vale dos Vinhedos & Encruzilhada do Sul', ARRAY['Lidio Carraro', 'Lídio Carraro Vinhos', 'Vinhos Puristas', 'Quorum']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["volcanic_basalt","granite"],"climates":["diurnal_shift"],"waterBodies":[],"styles":["dry_red"],"vinification":["amphora_concrete_unoaked"],"sensory":["full_bodied_high_abv"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Merlot","Cabernet Sauvignon","Cabernet Franc","Tannat"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 76, 'Brazil''s ''purist'' winery: no oak at all, gravity-flow handling and no filtration, so the wines show only grape and site. Vineyards were planted in the Vale dos Vinhedos from 1998, on basaltic clay-sand, and at Encruzilhada do Sul from 2001, on granitic sandy soils; the Quorum blend joins Merlot, Cabernet Sauvignon, Cabernet Franc and Tannat.'),
  ('prod-guaspari', 'Vinícola Guaspari', 'Guaspari', 'producer', 'Brazil', 'Southeast Brazil', 'Espírito Santo do Pinhal (SP), Serra da Mantiqueira', ARRAY['Guaspari', 'Vinicola Guaspari', 'Vista do Chá']::text[], '{"countryCode":"BR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["granite"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red"],"vinification":["extended_aging_36m"],"sensory":["full_bodied_high_abv"],"varietalTraits":["rhone_family"],"primaryGrapes":["Syrah"],"bottleShapes":["burgundy_slope"],"heritage":[]}'::jsonb, 74, 'A São Paulo state estate in the Serra da Mantiqueira: the family arrived in 2001, planted in 2006 and made its first 30 bottles in 2008. Syrah grows at 1,000–1,140 m, and double pruning moves the harvest into the dry winter, in July and August. Syrah Vista do Chá spends 28 months in French oak and 32 more in bottle.'),
  ('prod-zuccardi', 'Zuccardi Valle de Uco', 'Zuccardi', 'producer', 'Argentina', 'Cuyo', 'Paraje Altamira GI, Uco Valley (Mendoza)', ARRAY['Zuccardi', 'Familia Zuccardi', 'Zuccardi Valle de Uco', 'Concreto']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["limestone_chalk"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red"],"vinification":["amphora_concrete_unoaked","carbonic_whole_cluster"],"sensory":["full_bodied_high_abv"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Malbec"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 40, 'The Zuccardi story began in 1963 with a vineyard planted to demonstrate an irrigation system. Its Paraje Altamira winery, opened in 2016, is built of uncoated concrete, and the Concreto Malbec is fermented whole-bunch and raised in concrete from stony, calcareous plots at 1,050–1,150 m.'),
  ('prod-achaval-ferrer', 'Achaval-Ferrer', 'Achaval-Ferrer', 'producer', 'Argentina', 'Cuyo', 'Paraje Altamira GI (Finca Altamira), Uco Valley', ARRAY['Achaval Ferrer', 'Achaval-Ferrer', 'Finca Altamira']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt","limestone_chalk","gravel_alluvial"],"climates":["high_altitude"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["violet_rose_floral","saline_mineral"],"varietalTraits":["bordeaux_family","single_varietal_strict"],"primaryGrapes":["Malbec"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 52, 'Founded in 1998 around single-vineyard Malbec from old Mendoza plantings dating to 1910, 1921, 1923 and 1950. Finca Altamira, planted in 1950 at 1,100 m on the south bank of the Tunuyán River, grows in volcanic ash over alluvial river stones rich in calcareous sediment; it ferments in small concrete tanks, goes through malolactic in new French oak and shows violets and minerality.'),
  ('prod-colome', 'Bodega Colomé', 'Colomé', 'producer', 'Argentina', 'North Argentina', 'Molinos GI, Calchaquí Valleys (Salta)', ARRAY['Colome', 'Colomé', 'Bodega Colomé', 'Altura Máxima']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["limestone_chalk","granite","gravel_alluvial"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red"],"vinification":["amphora_concrete_unoaked"],"sensory":["violet_rose_floral","low_tannin_delicate"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Malbec","Pinot Noir","Sauvignon Blanc"],"bottleShapes":["bordeaux_shoulder"],"heritage":["codified_pre_1855"]}'::jsonb, 50, 'Founded in 1831, Colomé is Argentina''s oldest continuously producing winery; the Hess family bought it in 2001. Its vineyards climb from 2,300 m to 3,111 m, and Altura Máxima, at 3,111 m on calcareous and granitic gravel, gives very floral wines with delicate tannins. Colomé Auténtico Malbec sees no oak at all.'),
  ('prod-chacra', 'Bodega Chacra', 'Chacra', 'producer', 'Argentina', 'Patagonia', 'Mainqué, Alto Valle del Río Negro', ARRAY['Chacra', 'Bodega Chacra', 'Treinta y Dos']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["gravel_alluvial"],"climates":["diurnal_shift"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["carbonic_whole_cluster"],"sensory":["saline_mineral"],"varietalTraits":["burgundy_family"],"primaryGrapes":["Pinot Noir","Chardonnay"],"bottleShapes":["burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","biodynamic_pioneer"]}'::jsonb, 56, 'Piero Incisa della Rocchetta, grandson of Sassicaia''s creator, makes Pinot Noir in Río Negro, including Treinta y Dos from ungrafted vines planted in 1932. The estate is certified biodynamic, its Chardonnay is made with Jean-Marc Roulot, and the gravelly soils see nights up to 40 degrees cooler than the days.'),
  ('prod-el-enemigo', 'El Enemigo (Bodega Aleanna)', 'El Enemigo', 'producer', 'Argentina', 'Cuyo', 'Gualtallary, Uco Valley (Mendoza GI)', ARRAY['El Enemigo', 'Bodega Aleanna', 'Aleanna', 'Gran Enemigo', 'Alejandro Vigil']::text[], '{"countryCode":"AR","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["limestone_chalk"],"climates":["high_altitude"],"waterBodies":[],"styles":["dry_red","dry_white"],"vinification":["carbonic_whole_cluster","amphora_concrete_unoaked","flor_yeast","large_neutral_botte_foudre"],"sensory":["laser_high_acid"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Cabernet Franc","Malbec","Chardonnay","Bonarda"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 55, 'Alejandro Vigil''s Bodega Aleanna. Gran Enemigo Gualtallary (85% Cabernet Franc, 15% Malbec) comes from calcareous, rocky soils at 1,470 m, with 40% whole bunches, fermented and aged in concrete, at pH 3.03; the 2013 scored 100 points from Wine Advocate. The Chardonnay ages under a veil of flor and the Bonarda in large foudres.'),
  ('prod-almaviva', 'Almaviva', 'Almaviva', 'producer', 'Chile', 'Central Valley', 'Puente Alto, Maipo Valley', ARRAY['Almaviva', 'Viña Almaviva']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["gravel_alluvial"],"climates":["mediterranean","high_altitude"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["violet_rose_floral"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Carménère","Cabernet Franc","Merlot","Petit Verdot"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 34, 'A 1997 partnership between Baron Philippe de Rothschild and Concha y Toro, launched in 1998 as Chile''s first ''château concept'' wine. Its 65 ha lie at 650 m on alluvial soils on the north bank of the Maipo River in Puente Alto; the 1997 blend was 72% Cabernet Sauvignon, 23% Carménère and 5% Cabernet Franc, aged 16 months in new French oak.'),
  ('prod-don-melchor', 'Don Melchor', 'Don Melchor', 'producer', 'Chile', 'Central Valley', 'Puente Alto, Maipo Valley', ARRAY['Don Melchor', 'Viña Don Melchor']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["gravel_alluvial"],"climates":["mediterranean","high_altitude"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["violet_rose_floral","long_cellar_20yr"],"varietalTraits":["bordeaux_family"],"primaryGrapes":["Cabernet Sauvignon","Cabernet Franc","Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 36, 'Puente Alto Cabernet Sauvignon first made in 1987 as a 100% varietal. The vineyard sits at 650 m on stony soils on the north bank of the Maipo River and is farmed as 7 parcels and 151 micro-parcels. The 2021 (93% Cabernet Sauvignon) spent 15 months in French oak, 68% new, shows violets, and the winery gives it 35–40 years of ageing potential; Wine Spectator named it Wine of the Year.'),
  ('prod-clos-apalta', 'Clos Apalta', 'Clos Apalta', 'producer', 'Chile', 'Central Valley', 'Apalta, Colchagua Valley', ARRAY['Clos Apalta', 'Lapostolle Clos Apalta', 'Lapostolle']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["granite"],"climates":["mediterranean","diurnal_shift"],"waterBodies":["major_river"],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["rotundone_black_pepper"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Carménère","Cabernet Sauvignon","Merlot"],"bottleShapes":["bordeaux_shoulder"],"heritage":["ungrafted_pre_phylloxera"]}'::jsonb, 40, 'A Carménère-led blend from Apalta, whose oldest plots were planted between 1915 and 1920. Its 40 ha of own-rooted vines grow on granite near the Tinguiririca River in a semi-Mediterranean climate with extreme day-night swings. The 2021 (75% Carménère) went through malolactic in new French oak, aged 21 months in barrels 78% new, and shows black pepper.'),
  ('prod-sena', 'Seña', 'Seña', 'producer', 'Chile', 'Aconcagua', 'Ocoa, Aconcagua Valley', ARRAY['Sena', 'Seña', 'Viña Seña']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["volcanic_basalt","gravel_alluvial"],"climates":["mediterranean"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["long_cellar_20yr"],"varietalTraits":["bordeaux_family","multi_blend_tradition"],"primaryGrapes":["Cabernet Sauvignon","Carménère"],"bottleShapes":["bordeaux_shoulder"],"heritage":["biodynamic_pioneer"]}'::jsonb, 42, 'Founded in 1995 by Eduardo Chadwick and Robert Mondavi as a Chilean icon blend, now biodynamically farmed at Ocoa in the Aconcagua Valley, in a Mediterranean climate on volcanic andesite, colluvium and alluvium. The 1995 was 70% Cabernet Sauvignon and 30% Carménère, aged 14 months in new French oak; at the 2004 Berlin Tasting, Seña 2001 placed second, behind Viñedo Chadwick 2000.'),
  ('prod-montes', 'Viña Montes', 'Montes', 'producer', 'Chile', 'Central Valley', 'Apalta, Colchagua Valley', ARRAY['Montes', 'Viña Montes', 'Montes Folly', 'Purple Angel', 'Montes Alpha M']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":["GI"],"soils":["granite","gravel_alluvial"],"climates":["diurnal_shift"],"waterBodies":[],"styles":["dry_red"],"vinification":["new_french_oak"],"sensory":["rotundone_black_pepper"],"varietalTraits":["rhone_family","bordeaux_family"],"primaryGrapes":["Syrah","Carménère","Cabernet Sauvignon"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 44, 'First harvest in 1987, founded in 1988 as Discover Wines. Montes says it introduced Syrah to Chile in 1993, bought its Apalta estate in 1995, launched Chile''s first icon wine, Alpha M, in 1996, the Syrah Folly in 2000, and Purple Angel, Chile''s first icon Carménère, in 2003; Folly comes from the highest slopes of La Finca de Apalta.'),
  ('prod-de-martino', 'De Martino (Viejas Tinajas)', 'De Martino', 'producer', 'Chile', 'Southern Chile', 'Guarilihue, Itata Valley', ARRAY['De Martino', 'Viña De Martino', 'Viejas Tinajas']::text[], '{"countryCode":"CL","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"temperate_mid","coastalOrIsland":false,"classifications":["GI"],"soils":["granite"],"climates":["maritime"],"waterBodies":["pacific_ocean"],"styles":["dry_red"],"vinification":["amphora_concrete_unoaked","carbonic_whole_cluster"],"sensory":["violet_rose_floral","low_tannin_delicate"],"varietalTraits":["rhone_family"],"primaryGrapes":["Cinsault"],"bottleShapes":["burgundy_slope"],"heritage":["ungrafted_pre_phylloxera","bush_vines"]}'::jsonb, 62, 'De Martino''s Viejas Tinajas Cinsault comes from Guarilihue in coastal Itata, 22 km from the Pacific, on decomposed granite: the vineyard was planted in 1982 without rootstock, gobelet-trained and dry-farmed. Whole berries ferment semi-carbonically in century-old clay tinajas, and the wine is floral, with violets, fine smooth tannins and 12.5% alcohol.'),
  ('prod-garzon', 'Bodega Garzón', 'Garzón', 'producer', 'Uruguay', 'Maldonado', 'Garzón, Maldonado (18 km from the Atlantic)', ARRAY['Garzon', 'Garzón', 'Bodega Garzón']::text[], '{"countryCode":"UY","originCountries":[],"alsoCountries":[],"alsoRegions":[],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["granite"],"climates":["maritime"],"waterBodies":["atlantic_ocean"],"styles":["dry_red","dry_white"],"vinification":["sur_lie_autolysis","large_neutral_botte_foudre"],"sensory":["saline_mineral"],"varietalTraits":["iberian_indigenous"],"primaryGrapes":["Tannat","Albariño"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 55, 'A Maldonado estate 18 km from the Atlantic Ocean, whose steady sea breeze freshens the vines, on weathered rock from Uruguay''s ancient crystalline basement (''ballast'') with exposed granite. Its Albariño spends 3–6 months on fine lees and is fresh and mineral, while top Tannats age 12–18 months in large, relatively neutral 1,500–2,500-litre vats.'),
  ('prod-bouza', 'Bodega Bouza', 'Bouza', 'producer', 'Uruguay', 'Montevideo', 'Melilla (Montevideo) & Las Violetas (Canelones)', ARRAY['Bouza', 'Bodega Bouza']::text[], '{"countryCode":"UY","originCountries":[],"alsoCountries":[],"alsoRegions":["Canelones"],"world":"New World","hemisphere":"Southern","latitudeBand":"warm_subtropical","coastalOrIsland":false,"classifications":[],"soils":["clay_limestone"],"climates":["maritime"],"waterBodies":["atlantic_ocean"],"styles":["dry_white","dry_red"],"vinification":["sur_lie_autolysis","new_french_oak"],"sensory":["high_tannin_high_acid"],"varietalTraits":["iberian_indigenous","bordeaux_family"],"primaryGrapes":["Albariño","Tannat","Tempranillo","Merlot","Chardonnay"],"bottleShapes":["bordeaux_shoulder"],"heritage":[]}'::jsonb, 70, 'A Galician-rooted family winery that began in 1998 with a 35-year-old vineyard in Las Violetas, Canelones, and in 2001 restored a 1950s winery at Melilla, Montevideo, in a temperate, Atlantic-influenced climate. It planted Albariño and Tempranillo next to the inherited Chardonnay, Merlot and Tannat; the Albariño spends 4 months on its lees, and the B6 single-parcel Tannat ages 12 months in new French and American oak.')
